def css_prop(prop, value):
    return ': '.join([prop, value])


def css_important(value):
    return ' '.join([value, '!important'])


def css_class(name, rules):
    return ''.join(['.', name, ' { ', rules, ' }'])


def css_id(name, rules):
    return ''.join(['#', name, ' { ', rules, ' }'])


def css_media_query(condition, rules):
    return ' '.join(['@media', condition, '{', rules, '}'])


def css_pseudo(selector, pseudo):
    return ':'.join([selector, pseudo])


def css_child(parent, child):
    return ' > '.join([parent, child])


def css_sibling(el1, el2):
    return ' + '.join([el1, el2])


def css_rule(selector, rules):
    return ''.join([selector, ' { ', rules, ' }'])


def main():
    button_body = '; '.join([
        css_prop('color', '#fff'),
        css_prop('background', css_important('#06c')),
        css_prop('padding', '4px 12px'),
    ])
    button = css_class('button', button_body)
    header = css_id('header', css_prop('height', '64px'))
    hover = css_rule(css_pseudo('.button', 'hover'),
                     css_prop('background', '#048'))
    nav_body = '; '.join([css_prop('margin', '0'), css_prop('padding', '0')])
    nested = css_rule(css_child('nav', 'ul'), nav_body)
    adjacent = css_rule(css_sibling('h1', 'p'),
                        css_prop('margin-top', '0.5em'))
    narrow = css_media_query('(max-width: 600px)',
                             css_rule('body', css_prop('font-size', '14px')))
    selectors = ', '.join([
        css_pseudo('a', 'visited'),
        css_child('table', 'tbody'),
        css_sibling('li', 'li'),
    ])
    reset = css_rule(selectors, css_prop('outline', 'none'))

    sheet = '\n'.join([button, header, hover, nested, adjacent, narrow, reset])
    print(sheet)


if __name__ == '__main__':
    main()

