ATTRIBUTE_ORDER = ['UID', 'CN', 'OU', 'O', 'DC', 'C']
SPECIAL_CHARS = {',', '+', '"', '\\', '<', '>', ';', '='}


def escape_rdn_value(value):
    if not value or not value.strip():
        raise ValueError('RDN value must be a non-empty string')
    chars = ['\\' + ch if ch in SPECIAL_CHARS else ch for ch in value.strip()]
    return ''.join(chars)


def build_cn(name):
    return '='.join(['CN', escape_rdn_value(name)])


def build_ou(unit):
    return '='.join(['OU', escape_rdn_value(unit)])


def build_dc(domain):
    return '='.join(['DC', escape_rdn_value(domain)])


def build_o(org):
    return '='.join(['O', escape_rdn_value(org)])


def build_c(country):
    code = escape_rdn_value(country).upper()
    if len(code) != 2:
        raise ValueError('Country must be a two-letter code, got ' + code)
    return '='.join(['C', code])


def build_uid(uid):
    return '='.join(['UID', escape_rdn_value(uid)])


def build_dn_2(part1, part2):
    return ','.join([part1, part2])


def build_dn_3(part1, part2, part3):
    return ','.join([part1, part2, part3])


def build_domain_components(fqdn):
    labels = [label for label in fqdn.split('.') if label]
    return ','.join(build_dc(label) for label in labels)


def describe_dn(dn):
    seen = []
    for rdn in dn.split(','):
        attr = rdn.split('=', 1)[0].upper()
        if attr not in seen:
            seen.append(attr)
    ordered = [attr for attr in ATTRIBUTE_ORDER if attr in seen]
    extra = [attr for attr in seen if attr not in ATTRIBUTE_ORDER]
    return ', '.join(ordered + extra)


def main():
    base = build_domain_components('example.com')
    org_branch = build_dn_2(build_o('Example Corp'), base)
    people = build_dn_3(build_ou('People'), build_o('Example Corp'), base)
    user_dn = build_dn_2(build_cn('Doe, Jane'), people)
    service_dn = build_dn_3(build_uid('svc-backup'), build_ou('Services'), org_branch)
    country_dn = build_dn_2(org_branch, build_c('us'))

    print('Organisation : ' + org_branch)
    print('People branch: ' + people)
    print('User DN      : ' + user_dn)
    print('Service DN   : ' + service_dn)
    print('Country DN   : ' + country_dn)
    print('User attrs   : ' + describe_dn(user_dn))
    print('Service attrs: ' + describe_dn(service_dn))


if __name__ == '__main__':
    main()

