def latex_frac(num, den):
    return ''.join(['\\frac{', num, '}{', den, '}'])


def latex_super(base, exp):
    return ''.join([base, '^{', exp, '}'])


def latex_sub(base, sub):
    return ''.join([base, '_{', sub, '}'])


def latex_int(lower, upper, expr):
    return ''.join(['\\int_{', lower, '}^{', upper, '} ', expr])


def latex_sum(lower, upper, expr):
    return ''.join(['\\sum_{', lower, '}^{', upper, '} ', expr])


def latex_sqrt(expr):
    return ''.join(['\\sqrt{', expr, '}'])


def latex_limit(var, val, expr):
    return ''.join(['\\lim_{', var, '\\to ', val, '} ', expr])


def latex_vec(name):
    return ''.join(['\\vec{', name, '}'])


def latex_pair(first, second):
    return ', '.join([first, second])


def latex_call(name, args):
    return ''.join([name, '(', args, ')'])


def latex_equation(lhs, rhs):
    return ' = '.join([lhs, rhs])


def display_block(body):
    return '\n'.join(['\\[', '    ' + body, '\\]'])


def describe(label, code):
    return ': '.join([label, code])


def main():
    geometric = latex_sum('n = 0', '\\infty', latex_frac('1', latex_super('2', 'n')))
    gaussian = latex_int('-\\infty', '\\infty', latex_super('e', '-x^{2}'))
    derivative = latex_limit('h', '0', latex_frac('f(x + h) - f(x)', 'h'))
    norm = latex_sqrt(latex_call('g', latex_pair(latex_vec('v'), latex_vec('v'))))
    indexed = latex_sub('a', latex_super('i', '2'))

    catalogue = [
        ('geometric series', geometric),
        ('gaussian integral', gaussian),
        ('derivative of f', derivative),
        ('vector norm', norm),
        ('indexed term', indexed),
    ]
    for label, code in catalogue:
        print(describe(label, code))
    print()

    print(display_block(latex_equation(geometric, '2')))
    print()
    print(display_block(latex_equation(gaussian, latex_sqrt('\\pi'))))
    print()
    two_variable = latex_call('f', latex_pair('x', 'y'))
    print(display_block(latex_equation(two_variable, derivative)))


if __name__ == '__main__':
    main()

