def _clean(value):
    return str(value).strip().replace(' ', '')


def iban_format(cc, check, bban):
    return ''.join([_clean(cc).upper(), _clean(check), _clean(bban).upper()])


def bban_format(bank, branch, acc):
    return ''.join([_clean(bank).upper(), _clean(branch), _clean(acc)])


def sort_code(p1, p2, p3):
    return '-'.join([_clean(p1), _clean(p2), _clean(p3)])


def swift_bic(bank, country, loc, branch):
    return ''.join([_clean(bank).upper(), _clean(country).upper(),
                    _clean(loc).upper(), _clean(branch).upper()])


def routing_acc(routing, acc):
    return ':'.join([_clean(routing), _clean(acc)])


def card_num(g1, g2, g3, g4):
    return ' '.join([_clean(g1), _clean(g2), _clean(g3), _clean(g4)])


def expiry_date(month, year):
    return '/'.join([_clean(month).zfill(2), _clean(year)])


def check_routing(transit, inst, acc):
    return '-'.join([_clean(transit), _clean(inst), _clean(acc)])


def describe(label, value):
    return ''.join([label.ljust(14), ' = ', value])


def main():
    bban = bban_format('NWBK', ' 601613 ', '31926819')
    iban = iban_format('gb', '29', bban)
    cases = [
        ('BBAN', bban, 'NWBK60161331926819'),
        ('IBAN', iban, 'GB29NWBK60161331926819'),
        ('sort code', sort_code('60', '16', '13'), '60-16-13'),
        ('SWIFT/BIC', swift_bic('nwbk', 'gb', '2l', 'xxx'), 'NWBKGB2LXXX'),
        ('routing/acc', routing_acc('021000021', '12345678'),
         '021000021:12345678'),
        ('card', card_num('4111', '1111', '1111', '1111'),
         '4111 1111 1111 1111'),
        ('expiry', expiry_date('7', '2029'), '07/2029'),
        ('cheque', check_routing('00012', '003', '123456789'),
         '00012-003-123456789'),
    ]
    failures = 0
    for label, actual, expected in cases:
        if actual == expected:
            status = 'ok'
        else:
            status = ''.join(['MISMATCH (expected ', expected, ')'])
            failures += 1
        print(describe(label, ' '.join([actual, status])))
    if failures:
        print(''.join(['FAILED: ', str(failures), ' of ', str(len(cases))]))
    else:
        print(' '.join(['OK:', str(len(cases)), 'formats verified']))


if __name__ == '__main__':
    main()

