    return '/'.join([_device_prefix(tenant, device_id), 'telemetry'])


def get_command_topic(tenant, device_id, command_name):
    _validate('command_name', command_name)
    return '/'.join([_device_prefix(tenant, device_id), 'commands', command_name])


def get_status_topic(tenant, device_id):
    return '/'.join([_device_prefix(tenant, device_id), 'status'])


def get_alert_topic(tenant, device_id, severity):
    _validate('severity', severity)
    level = severity.lower()
    if level not in SEVERITIES:
        raise ValueError(''.join(['unknown severity: ', severity]))
    return '/'.join([_device_prefix(tenant, device_id), 'alerts', level])


