def _quote_param(value):
    if any(ch in value for ch in ':;,'):
        return ''.join(['"', value.replace('"', ''), '"'])
    return value


def _format_params(params):
    chunks = []
    for name, value in params:
        chunks.append(''.join([';', name, '=', _quote_param(value)]))
    return ''.join(chunks)


def _property_line(name, params, value):
    return ''.join([name, _format_params(params), ':', value])


def escape_text(text):
    mapping = {'\\': '\\\\', ';': '\\;', ',': '\\,', '\n': '\\n'}
    return ''.join([mapping.get(ch, ch) for ch in text])


def _validate_date(date_string):
    if not DATE_PATTERN.fullmatch(date_string):
        raise ValueError(', '.join([
            'invalid date-time value ' + repr(date_string),
            'expected YYYYMMDD or YYYYMMDDTHHMMSS[Z]']))
    return date_string


def _date_property(name, date_string, tzid):
    _validate_date(date_string)
    params = []
    if len(date_string) == 8:
        params.append(('VALUE', 'DATE'))
    if tzid:
        if date_string.endswith('Z'):
            raise ValueError('TZID must not be combined with a UTC value')
        params.append(('TZID', tzid))
    return _property_line(name, params, date_string)


