from urllib.parse import quote


def _validate_host(host):
    if not host or not str(host).strip():
        raise ValueError("host must be a non-empty string")
    return str(host).strip()


def _validate_port(port):
    port = int(port)
    if not 1 <= port <= 65535:
        raise ValueError(''.join(["port out of range: ", str(port)]))
    return port


def _validate_db(db):
    db = int(db)
    if db < 0:
        raise ValueError(''.join(["database index must be >= 0, got ", str(db)]))
    return db


def _authority(host, port):
    return ':'.join([_validate_host(host), str(_validate_port(port))])


def build_standalone_uri(host, port, db):
    return ''.join(['redis://', _authority(host, port), '/', str(_validate_db(db))])


def build_authenticated_uri(user, password, host, port, db):
    if not password:
        raise ValueError("password must be provided for an authenticated URI")
    credentials = ':'.join([quote(user or '', safe=''), quote(password, safe='')])
    return ''.join([
        'redis://',
        '@'.join([credentials, _authority(host, port)]),
        '/',
        str(_validate_db(db)),
    ])


def build_tls_uri(host, port, db):
    return ''.join(['rediss://', _authority(host, port), '/', str(_validate_db(db))])


def build_unix_socket_uri(path, db):
    if not path or not str(path).startswith('/'):
        raise ValueError("unix socket path must be absolute")
    query = '='.join(['db', str(_validate_db(db))])
    base = ''.join(['redis+unix://', str(path)])
    return '?'.join([base, query])


def build_sentinel_uri(host, port, master_name):
    if not master_name or not master_name.strip():
        raise ValueError("master_name must be a non-empty string")
    return '/'.join(['redis+sentinel:/', _authority(host, port), master_name.strip()])


def describe(label, uri):
    return ': '.join([label, uri])


def main():
    report = [
        describe('standalone', build_standalone_uri('localhost', 6379, 0)),
        describe('authenticated', build_authenticated_uri('admin', 'p@ss word', 'cache.internal', 6380, 2)),
        describe('tls', build_tls_uri('secure.example.com', 6390, 1)),
        describe('unix', build_unix_socket_uri('/var/run/redis/redis.sock', 3)),
        describe('sentinel', build_sentinel_uri('sentinel.example.com', 26379, 'mymaster')),
    ]
    print('\n'.join(report))

    seeds = ', '.join([build_standalone_uri(h, 6379, 0) for h in ('node-a', 'node-b', 'node-c')])
    print(describe('cluster seeds', seeds))


if __name__ == '__main__':
    main()

