    return '^XA'


def build_end_format():
    return '^XZ'


def _position(x, y):
    return ''.join(['^FO', str(int(x)), ',', str(int(y))])


def _font(height, width):
    return ''.join(['^A0N,', str(int(height)), ',', str(int(width))])


def escape_data(text):
    escaped = str(text).replace('\\', '\\\\')
    escaped = escaped.replace('^', '\\^')
    return escaped.replace('~', '\\~')


def build_text_field(x, y, font, text):
    height, width = font if isinstance(font, tuple) else (font, font)
    return ''.join([_position(x, y), _font(height, width), '^FD', escape_data(text), '^FS'])


def build_barcode_field(x, y, data):
    payload = str(data)
    if not payload.isdigit() or len(payload) % 2 != 0:
        raise ValueError(''.join(['Interleaved 2 of 5 needs an even count of digits, got: ', payload]))
    return ''.join([_position(x, y), '^BY2^B2N,50,Y,N,N^FD', payload, '^FS'])


def build_qr_code(x, y, data):
    return ''.join([_position(x, y), '^BQN,2,6', '^FDLA,', escape_data(data), '^FS'])


def format_row(x, y, command):
    return ' | '.join([str(x), str(y), command])


