def format_track1(pan, name, exp_date, svc_code):
    clean_pan = clean_numeric(pan)
    name_upper = str(name).upper()
    return ''.join(['%B', clean_pan, '^', name_upper, '^', str(exp_date), str(svc_code), '?'])

