    return _command('G1', [('X', x), ('Y', y), ('Z', z), ('F', f)])


def rapid_move(x=None, y=None, z=None):
    return _command('G0', [('X', x), ('Y', y), ('Z', z)])


def set_spindle_speed(s):
    if s < 0:
        raise ValueError(''.join(['negative spindle speed: ', _fmt(s)]))
    return _command('M3', [('S', s)])


