import re

LITERAL_SPECIALS = r'([+\-&|!(){}\[\]^"~*?:\\/ ])'
WILDCARD_SPECIALS = r'([+\-&|!(){}\[\]^"~:\\/ ])'


def escape_term(text):
    """Escape every Lucene special character in a literal term."""
    return re.sub(LITERAL_SPECIALS, r'\\\1', str(text))


def escape_pattern(pattern):
    """Escape specials but leave the wildcards '*' and '?' active."""
    return re.sub(WILDCARD_SPECIALS, r'\\\1', str(pattern))


def check_field(field):
    """Field names must be present; surrounding blanks are dropped."""
    if not field or not str(field).strip():
        raise ValueError('field name must be a non-empty string')
    return str(field).strip()


def build_term_query(field, term):
    """title:lucene -- a single escaped term on one field."""
    return ''.join([check_field(field), ':', escape_term(term)])


def build_wildcard_query(field, pattern):
    """title:luc*ne -- '*' and '?' stay live, everything else is escaped."""
    if not str(pattern).strip('*?'):
        raise ValueError('wildcard pattern needs at least one literal character')
    return ''.join([check_field(field), ':', escape_pattern(pattern)])


def build_fuzzy_query(field, term, distance):
    """title:lucene~2 -- edit distance must be 0, 1 or 2."""
    if int(distance) not in (0, 1, 2):
        raise ValueError('fuzzy edit distance must be 0, 1 or 2')
    return ''.join([check_field(field), ':', escape_term(term), '~', str(int(distance))])


def build_range_query(field, start, end):
    """date:[20020101 TO 20030101] -- inclusive range, '*' means open ended."""
    bounds = ' TO '.join([escape_term(start), escape_term(end)])
    return ''.join([check_field(field), ':[', bounds, ']'])


def build_boosted_query(query, boost_factor):
    """(title:lucene)^4 -- wrap in parentheses unless already wrapped."""
    boost = float(boost_factor)
    if boost <= 0:
        raise ValueError('boost factor must be positive')
    text = str(query)
    if text.startswith('(') and text.endswith(')'):
        body = text
    else:
        body = ''.join(['(', text, ')'])
    return ''.join([body, '^', '%g' % boost])


def combine(operator, left, right):
    """Join two sub-queries with AND/OR into a parenthesised clause."""
    if operator.upper() not in ('AND', 'OR'):
        raise ValueError('operator must be AND or OR')
    return ''.join(['(', left, ' ', operator.upper(), ' ', right, ')'])


def format_row(name, query):
    """One human readable line for a generated query."""
    return ': '.join([name.ljust(9), query])


def main():
    rows = [
        ('term', build_term_query('title', 'lucene')),
        ('wildcard', build_wildcard_query('title', 'luc*ne')),
        ('fuzzy', build_fuzzy_query('author', 'doug cutting', 1)),
        ('range', build_range_query('date', '20020101', '20030101')),
    ]
    recent = combine('AND', rows[0][1], rows[3][1])
    rows.append(('boosted', build_boosted_query(recent, 4)))
    rows.append(('mixed', combine('OR', rows[1][1], rows[2][1])))
    for name, query in rows:
        print(format_row(name, query))


if __name__ == '__main__':
    main()

