ESC = '\033['
RESET = ESC + '0m'


def rgb_fg(r, g, b, text):
    params = ';'.join(['38', '2', r, g, b])
    return ''.join([ESC, params, 'm', text, RESET])


def rgb_bg(r, g, b, text):
    params = ';'.join(['48', '2', r, g, b])
    return ''.join([ESC, params, 'm', text, RESET])


def cursor_move(row, col):
    position = ';'.join([row, col])
    return ''.join([ESC, position, 'H'])


def clear_screen(mode):
    modes = {'end': '0', 'start': '1', 'all': '2', 'scrollback': '3'}
    if mode not in modes:
        raise ValueError(''.join(['unknown clear mode: ', repr(mode)]))
    return ''.join([ESC, modes[mode], 'J'])


def set_title(title):
    return ''.join(['\033]0;', title, '\007'])


def draw_box_chars(tl, tr, bl, br):
    top = ''.join([tl, tr])
    bottom = ''.join([bl, br])
    return '\n'.join([top, bottom])


def hyperlink(url, text):
    opener = ''.join(['\033]8;;', url, '\033\\'])
    return ''.join([opener, text, '\033]8;;\033\\'])


def scroll_region(top, bottom):
    bounds = ';'.join([top, bottom])
    return ''.join([ESC, bounds, 'r'])


def render_panel(title, url, link_text, width, height):
    box = draw_box_chars('+', '+', '+', '+')
    corners = box.splitlines()
    rule = '-' * (int(width) - 2)
    frame = ''.join([corners[0][0], rule, corners[0][1]])
    footer = ''.join([corners[1][0], rule, corners[1][1]])
    body = ''.join([cursor_move('2', '2'), hyperlink(url, link_text)])
    return ''.join([
        set_title(title),
        scroll_region('1', height),
        clear_screen('all'),
        cursor_move('1', '1'),
        frame,
        body,
        cursor_move(height, '1'),
        footer,
    ])


def describe(sequence):
    visible = sequence.replace('\033', '\\033').replace('\007', '\\007')
    return ', '.join(['length=' + str(len(sequence)), 'raw=' + visible])


def main():
    alerts = [rgb_fg('255', '0', '0', 'Error'), rgb_bg('0', '0', '128', 'Info')]
    print(' | '.join(alerts))
    panel = render_panel('Dashboard', 'https://example.com', 'docs', '40', '12')
    print(describe(panel))
    print(describe(draw_box_chars('\u250c', '\u2510', '\u2514', '\u2518')))


if __name__ == '__main__':
