_MEAS_SPECIALS = ((",", "\\,"), (" ", "\\ "))
_KEY_SPECIALS = ((",", "\\,"), (" ", "\\ "), ("=", "\\="))


def _escape(text, specials):
    escaped = text
    for raw, replacement in specials:
        escaped = escaped.replace(raw, replacement)
    return escaped


def _measurement(meas):
    if not meas:
        raise ValueError("measurement must not be empty")
    return _escape(meas, _MEAS_SPECIALS)


def _tag(key, value):
    if not key or not value:
        raise ValueError("tag keys and values must not be empty")
    return ''.join([_escape(key, _KEY_SPECIALS), "=", _escape(value, _KEY_SPECIALS)])


def _field(key, value):
    if not key:
        raise ValueError("field keys must not be empty")
    return ''.join([_escape(key, _KEY_SPECIALS), "=", value])


def _int_value(raw):
    return ''.join([str(int(raw)), "i"])


def _float_value(raw):
    return repr(float(raw))


def _string_value(raw):
    inner = raw.replace("\\", "\\\\").replace('"', '\\"')
    return ''.join(['"', inner, '"'])


def _bool_value(raw):
    lowered = raw.strip().lower()
    if lowered in ("t", "true", "1", "yes"):
        return "true"
    if lowered in ("f", "false", "0", "no"):
        return "false"
    raise ValueError(''.join(["cannot read boolean from ", raw]))


def _line(key_part, field_part, ts):
    if ts is None:
        return ''.join([key_part, " ", field_part])
    return ''.join([key_part, " ", field_part, " ", str(int(ts))])


def point_int(meas, tag_k, tag_v, field_k, field_v, ts):
    key = ''.join([_measurement(meas), ",", _tag(tag_k, tag_v)])
    return _line(key, _field(field_k, _int_value(field_v)), ts)


def point_float(meas, tag_k, tag_v, field_k, field_v, ts):
    key = ''.join([_measurement(meas), ",", _tag(tag_k, tag_v)])
    return _line(key, _field(field_k, _float_value(field_v)), ts)


def point_string(meas, tag_k, tag_v, field_k, field_v, ts):
    key = ''.join([_measurement(meas), ",", _tag(tag_k, tag_v)])
    return _line(key, _field(field_k, _string_value(field_v)), ts)


def point_boolean(meas, tag_k, tag_v, field_k, field_v, ts):
    key = ''.join([_measurement(meas), ",", _tag(tag_k, tag_v)])
    return _line(key, _field(field_k, _bool_value(field_v)), ts)


def point_two_tags(meas, t1_k, t1_v, t2_k, t2_v, f_k, f_v, ts):
    key = ''.join([_measurement(meas), ",", _tag(t1_k, t1_v), ",", _tag(t2_k, t2_v)])
    return _line(key, _field(f_k, _int_value(f_v)), ts)


def point_two_fields(meas, t_k, t_v, f1_k, f1_v, f2_k, f2_v, ts):
    key = ''.join([_measurement(meas), ",", _tag(t_k, t_v)])
    fields = ''.join([_field(f1_k, _int_value(f1_v)), ",", _field(f2_k, _int_value(f2_v))])
    return _line(key, fields, ts)


def point_no_tags(meas, f_k, f_v, ts):
    return _line(_measurement(meas), _field(f_k, _int_value(f_v)), ts)


def point_no_ts(meas, t_k, t_v, f_k, f_v):
    key = ''.join([_measurement(meas), ",", _tag(t_k, t_v)])
    return _line(key, _field(f_k, _int_value(f_v)), None)


def main():
    batch = [
        point_int("cpu", "host", "serverA", "usage", "85", "164099"),
        point_float("cpu", "host", "server A", "load", "0.64", "164100"),
        point_string("syslog", "host", "serverA", "msg", 'disk "sda" busy', "164101"),
        point_boolean("health", "host", "serverA", "up", "yes", "164102"),
        point_two_tags("mem", "host", "serverA", "region", "eu-west", "used", "2048", "164103"),
        point_two_fields("net", "host", "serverA", "rx", "1200", "tx", "980", "164104"),
        point_no_tags("uptime", "seconds", "99999", "164105"),
        point_no_ts("cpu,core", "host", "serverA", "usage", "12"),
    ]
    for line in batch:
        print(line)
    print(''.join([str(len(batch)), " points built"]))


if __name__ == "__main__":
    main()

