_TRUTHY = {"yes", "true", "1", "on", "nocase"}


def _validate_sid(sid):
    if not sid.isdigit():
        raise ValueError(''.join(["invalid sid: ", sid]))
    return sid


def _options(msg, sid):
    message = ''.join(['msg:"', msg, '"'])
    identifier = ''.join(['sid:', _validate_sid(sid)])
    body = '; '.join([message, identifier])
    return ''.join(['(', body, ';)'])


def _rule(action, proto, src, sport, dst, dport, msg, sid):
    header = ' '.join([action, proto, src, sport, "->", dst, dport])
    return ' '.join([header, _options(msg, sid)])


def alert_tcp(src, sport, dst, dport, msg, sid):
    return _rule("alert", "tcp", src, sport, dst, dport, msg, sid)


def alert_udp(src, sport, dst, dport, msg, sid):
    return _rule("alert", "udp", src, sport, dst, dport, msg, sid)


def alert_icmp(src, dst, msg, sid):
    return _rule("alert", "icmp", src, "any", dst, "any", msg, sid)


def alert_http(src, dst, msg, sid):
    return _rule("alert", "http", src, "any", dst, "any", msg, sid)


def rule_flow(direction, state):
    return ''.join(['flow:', direction, ',', state, ';'])


def rule_content(content, nocase):
    match = ''.join(['content:"', content, '";'])
    if nocase.strip().lower() in _TRUTHY:
        return ''.join([match, ' nocase;'])
    return match


def rule_pcre(regex):
    return ''.join(['pcre:"/', regex, '/";'])


def drop_ip(src, dst, msg, sid):
    return _rule("drop", "ip", src, "any", dst, "any", msg, sid)


def with_option(rule, option):
    head, _, tail = rule.partition("(")
    return ''.join([head, "(", tail[:-1].strip(), " ", option, ")"])


def main():
    web = alert_tcp("$HOME_NET", "any", "$EXTERNAL_NET", "80", "HTTP Traffic", "1000001")
    web = with_option(web, rule_flow("to_server", "established"))
    web = with_option(web, rule_content("GET /admin", "yes"))
    dns = alert_udp("$HOME_NET", "any", "$EXTERNAL_NET", "53", "Suspicious DNS", "1000002")
    dns = with_option(dns, rule_content("dyndns", "true"))
    api = alert_http("$HOME_NET", "$EXTERNAL_NET", "Credential Leak", "1000004")
    api = with_option(api, rule_pcre("(?i)password=[^&]+"))
    sweep = alert_icmp("$EXTERNAL_NET", "$HOME_NET", "ICMP Sweep", "1000003")
    blocked = drop_ip("10.0.0.6", "$EXTERNAL_NET", "Blocked Host", "1000005")
    for rule in [web, dns, sweep, api, blocked]:
        print(rule)


if __name__ == "__main__":
    main()

