def _require(**fields):
    """Raise ValueError if any property component is blank."""
    for name, value in sorted(fields.items()):
        if not value.strip():
            raise ValueError('blank property component: ' + name)


def geom_absolute(w, h, x, y):
    _require(w=w, h=h, x=x, y=y)
    return w + 'x' + h + '+' + x + '+' + y


def geom_relative(w, h, x_pct, y_pct):
    _require(w=w, h=h, x_pct=x_pct, y_pct=y_pct)
    size = w + 'x' + h
    x_off = x_pct + '%'
    y_off = y_pct + '%'
    return size + '+' + x_off + '+' + y_off


def win_title(class_name, instance, title):
    _require(class_name=class_name, instance=instance, title=title)
    return class_name + '.' + instance + '.' + title


def win_state(max_v, max_h, hidden):
    _require(max_v=max_v, max_h=max_h, hidden=hidden)
    return max_v + '+' + max_h + '+' + hidden


def win_motif(decor, func, input_mode):
    _require(decor=decor, func=func, input_mode=input_mode)
    return decor + '.' + func + '.' + input_mode


def win_pid_machine(pid, hostname):
    _require(pid=pid, hostname=hostname)
    return pid + '.' + hostname


def xrandr_out(name, mode, rate, pos):
    _require(name=name, mode=mode, rate=rate, pos=pos)
    return name + '.' + mode + '.' + rate + '.' + pos


def xprop_atom(name, atom_type, val):
    _require(name=name, atom_type=atom_type, val=val)
    return name + '.' + atom_type + '.' + val


def render_report(rows):
    """Turn (label, identifier) pairs into an aligned multi-line report."""
    width = max(len(label) for label, _ in rows)
    report = ''
    for label, value in rows:
        report += label.ljust(width) + '  ' + value + '\n'
    return report


def main():
    rows = [
        ('geometry', geom_absolute("800", "600", "100", "50")),
        ('geometry%', geom_relative("800", "600", "10", "20")),
        ('WM_CLASS', win_title("URxvt", "urxvt", "Terminal")),
        ('_NET_WM_STATE', win_state("MAXIMIZED_VERT", "MAXIMIZED_HORZ", "HIDDEN")),
        ('_MOTIF_WM_HINTS', win_motif("ALL", "RESIZE", "MODELESS")),
        ('_NET_WM_PID', win_pid_machine("4211", "workstation")),
        ('xrandr', xrandr_out("HDMI-1", "1920x1080", "60", "+0+0")),
        ('xprop', xprop_atom("_NET_WM_NAME", "UTF8_STRING", "Editor")),
    ]
    print(render_report(rows), end='')
    print('properties built: ' + str(len(rows)))
    try:
        xrandr_out("DP-2", "2560x1440", "  ", "")
    except ValueError as err:
        print('rejected: ' + str(err))


if __name__ == '__main__':
    main()

