    "dogecoin": "3",
    "ripple": "144",
    "cardano": "1815",
    "solana": "501",
}


def _hardened(value):
    return "".join([value, "'"])


def _validate(name, value):
    if not value.isdigit():
        raise ValueError("".join([name, " must be a decimal string, got ", repr(value)]))


def _path(coin_type, account, change, index):
    _validate("coin_type", coin_type)
    _validate("account", account)
    _validate("change", change)
    _validate("index", index)
    return "/".join(["m", PURPOSE, _hardened(coin_type), _hardened(account), change, index])


