def format_author(first, von, last, jr):
    parts = [p for p in (first, von, last, jr) if p]
    return ' '.join(parts)


def format_multiple_authors(a1, a2, a3):
    return ' and '.join([a1, a2, a3])


def format_pages(start, end):
    return '--'.join([str(start), str(end)])


