    return ', '.join([city, country])


def format_date(month, year):
    return ' '.join([month, str(year)])


def format_citation_key(author_last, year, word):
    return ''.join([author_last.lower(), str(year), word.lower()])


def format_keywords(k1, k2, k3):
    return ', '.join([k1, k2, k3])


def render_field(name, value):
    return ''.join(['  ', name, ' = {', value, '},'])


def render_entry(entry_type, key, fields):
    lines = [''.join(['@', entry_type, '{', key, ','])]
    for name, value in fields:
        lines.append(render_field(name, value))
    lines.append('}')
    return '\n'.join(lines)


def describe_entry(key, fields):
    lookup = dict(fields)
    summary = ', '.join([lookup['author'], lookup['year'], lookup['title']])
    return ''.join([key, ': ', summary])


