def dox_brief(text):
    return ''.join(['@brief ', text])


def dox_param(name, direction, desc):
    tag = ''.join(['@param[', direction, ']'])
    return ' '.join([tag, name, desc])


def dox_return(desc):
    return ''.join(['@return ', desc])


def dox_throws(exception, desc):
    return ' '.join(['@throws', exception, desc])


def dox_see(ref):
    return ''.join(['@see ', ref])


def dox_note(text):
    return ''.join(['@note ', text])


def dox_warning(text):
    return ''.join(['@warning ', text])


def dox_deprecated(text):
    return ''.join(['@deprecated ', text])


def comment_line(line, indent):
    if line:
        return ''.join([indent, ' * ', line])
    return ''.join([indent, ' *'])


def comment_block(tag_lines, indent=''):
    lines = [''.join([indent, '/**'])]
    lines.extend(comment_line(line, indent) for line in tag_lines)
    lines.append(''.join([indent, ' */']))
    return lines


def doc_tags(brief, params, returns, throws, refs, notes, warnings, deprecated):
    tags = [dox_brief(brief), '']
    tags.extend(dox_param(name, direction, desc) for name, direction, desc in params)
    tags.append(dox_return(returns))
    tags.extend(dox_throws(exc, desc) for exc, desc in throws)
    tags.extend(dox_see(ref) for ref in refs)
    tags.extend(dox_note(text) for text in notes)
    tags.extend(dox_warning(text) for text in warnings)
    if deprecated is not None:
        tags.append(dox_deprecated(deprecated))
    return tags


def main():
    tags = doc_tags(
        brief='Load a configuration file from disk.',
        params=[('path', 'in', 'Path of the configuration file.'),
                ('out_config', 'out', 'Parsed configuration on success.'),
