        notes=['Relative paths are resolved against the working directory.'],
        warnings=['out_config is left untouched when parsing fails.'],
        deprecated='Use load_config_ex() instead; removed in 3.0.',
    )
    for line in comment_block(tags, '    '):
        print(line)
    print('    bool load_config(const std::string &path, Config &out_config, unsigned flags);')


if __name__ == '__main__':
