_SPECIAL = set(',+"\\<>;=')


def escape_value(val):
    """Escape a value according to the RFC 4514 rules for DN string encoding."""
    if not isinstance(val, str):
        raise TypeError("RDN values must be strings")
    pieces = []
    last = len(val) - 1
    for index, char in enumerate(val):
        if char in _SPECIAL or char == '#' and index == 0:
            pieces.append('\\' + char)
        elif char == ' ' and index in (0, last):
            pieces.append('\\ ')
        else:
            pieces.append(char)
    result = ''
    for piece in pieces:
        result = result + piece
    return result


def rdn_country(val):
    code = val.strip()
    if len(code) != 2 or not code.isalpha():
        raise ValueError("country code must be two letters, got %r" % (val,))
    return 'C' + '=' + escape_value(code.upper())


def rdn_organization(val):
    return 'O' + '=' + escape_value(val)


def rdn_org_unit(val):
    return 'OU' + '=' + escape_value(val)


def rdn_common_name(val):
    return 'CN' + '=' + escape_value(val)


def rdn_locality(val):
    return 'L' + '=' + escape_value(val)


def rdn_state(val):
    return 'ST' + '=' + escape_value(val)


def rdn_email(val):
    return 'EMAIL' + '=' + escape_value(val)


def rdn_domain_component(val):
    return 'DC' + '=' + escape_value(val)


def build_subject(rdns):
    """Join RDNs into a comma separated X.509 subject string."""
    result = ''
    for index, rdn in enumerate(rdns):
        if index:
            result = result + ', '
        result = result + rdn
    return result


def openssl_subject(rdns):
    """Render the same RDNs in the slash separated form used by OpenSSL."""
    joined = ''
    for index, rdn in enumerate(rdns):
        if index:
            joined = joined + '/'
        joined = joined + rdn
    return '/' + joined


def describe(rdns):
    rows = []
    for number, rdn in enumerate(rdns, 1):
        key, value = rdn.split('=', 1)
        rows.append('%2d.' % number + ' ' + key.ljust(6) + ' ' + value)
    result = ''
    for index, row in enumerate(rows):
        if index:
            result = result + '\n'
        result = result + row
    return result


def main():
