def make_target(target, prereqs):
    return ''.join([target, ': ', prereqs])


def make_command(cmd):
    return ''.join(['\t', cmd])


def make_var_assign(name, val):
    return ' '.join([name, '=', val])


def make_var_append(name, val):
    return ' '.join([name, '+=', val])


def make_include(file):
    return ''.join(['include ', file])


def make_phony(targets):
    return ''.join(['.PHONY: ', targets])


def make_comment(text):
    return ''.join(['# ', text])


def make_export(name, val):
    return ''.join(['export ', name, '=', val])


def rule(target, prereqs, commands):
    deps = ' '.join(prereqs)
    lines = [make_target(target, deps)]
    lines.extend(make_command(cmd) for cmd in commands)
    return lines


def compile_command(compiler, flags, sources, output):
    inputs = ' '.join(sources)
    return ' '.join([compiler, flags, '-o', output, inputs])


def build_makefile(config):
    lines = [make_comment(config['title']), '']
    lines.append(make_var_assign('CC', config['compiler']))
    cflags = ' '.join(config['cflags'])
    lines.append(make_var_assign('CFLAGS', cflags))
    for lib in config['libs']:
        lines.append(make_var_append('LDFLAGS', ''.join(['-l', lib])))
    lines.append(make_export('BUILD_DIR', config['build_dir']))
    lines.append('')
    for fragment in config['includes']:
        lines.append(make_include(fragment))
    lines.append('')
    phony = ['all'] + sorted(config['extra_phony'])
    lines.append(make_phony(' '.join(phony)))
    lines.append('')
    objects = [''.join([src.rsplit('.', 1)[0], '.o']) for src in config['sources']]
    lines.extend(rule('all', [config['target']], []))
    lines.append('')
    link = compile_command('$(CC)', '$(LDFLAGS)', ['$^'], '$@')
    lines.extend(rule(config['target'], objects, [link]))
    lines.append('')
    compile_object = compile_command('$(CC)', '$(CFLAGS) -c', ['$<'], '$@')
    lines.extend(rule('%.o', ['%.c'], [compile_object]))
    lines.append('')
    clean = ' '.join(['rm -f', config['target']] + objects)
    lines.extend(rule('clean', [], [clean]))
    lines.append('')
    report = ', '.join(objects)
    echo = ''.join(['@echo "objects: ', report, '"'])
    lines.extend(rule('list', [], [echo]))
    return '\n'.join(lines)


def main():
