def _rule(path, permission, prefix=None):
    head = ''.join([prefix, ' ']) if prefix else ''
    return ''.join([head, path, ' ', permission, ','])


def aa_read(path):
    return _rule(path, 'r')


def aa_write(path):
    return _rule(path, 'w')


def aa_execute(path):
    return _rule(path, 'ix')


def aa_deny_read(path):
    return _rule(path, 'r', 'deny')


def aa_deny_write(path):
    return _rule(path, 'w', 'deny')


def aa_owner_read(path):
    return _rule(path, 'r', 'owner')


def aa_owner_write(path):
    return _rule(path, 'w', 'owner')


def aa_audit_execute(path):
    return _rule(path, 'ix', 'audit')


RULE_BUILDERS = [
    ('read', aa_read),
    ('write', aa_write),
    ('execute', aa_execute),
    ('deny_read', aa_deny_read),
    ('deny_write', aa_deny_write),
    ('owner_read', aa_owner_read),
    ('owner_write', aa_owner_write),
    ('audit_execute', aa_audit_execute),
]


def build_profile(binary, path):
    body = [aa_read(path), aa_owner_write(path), aa_deny_write(path), aa_audit_execute(path)]
    indented = [''.join(['  ', rule]) for rule in body]
    header = ''.join([binary, ' flags=(complain) {'])
    return '\n'.join([header] + indented + ['}'])


def describe_rules(path):
    lines = []
    for name, builder in RULE_BUILDERS:
        lines.append(''.join([name.ljust(14), ': ', builder(path)]))
    return lines


def main():
    sample = '/etc/passwd'
    print(''.join(['AppArmor rules for ', sample]))
    for line in describe_rules(sample):
        print(line)
    print()
    print(build_profile('/usr/bin/cat', sample))
    print()
    names = ', '.join([entry[0] for entry in RULE_BUILDERS])
    print(''.join(['Generated rule kinds: ', names]))


if __name__ == '__main__':
    main()

