    return ''.join(["set xlabel '", label, "'"])


def gnuplot_ylabel(label):
    return ''.join(["set ylabel '", label, "'"])


def gnuplot_xrange(min_val, max_val):
    return ''.join(['set xrange [', min_val, ':', max_val, ']'])


def gnuplot_yrange(min_val, max_val):
    return ''.join(['set yrange [', min_val, ':', max_val, ']'])


def gnuplot_terminal(term, size):
    return ' '.join(['set terminal', term, 'size', size])


def gnuplot_output(filename):
    return ''.join(["set output '", filename, "'"])


def gnuplot_plot(filename, using_cols):
    return ''.join(["plot '", filename, "' using ", using_cols])


def using_spec(columns):
    return ':'.join(str(col) for col in columns)


def build_script(config):
    commands = [
        gnuplot_terminal(config['terminal'], config['size']),
        gnuplot_output(config['output']),
        gnuplot_title(config['title']),
        gnuplot_xlabel(config['xlabel']),
        gnuplot_ylabel(config['ylabel']),
        gnuplot_xrange(config['xrange'][0], config['xrange'][1]),
        gnuplot_yrange(config['yrange'][0], config['yrange'][1]),
    ]
    for source in config['sources']:
        commands.append(gnuplot_plot(source['data'], using_spec(source['columns'])))
    return '\n'.join(commands)


def describe_config(config):
    ranges = ', '.join([
        'x=[{0}:{1}]'.format(*config['xrange']),
        'y=[{0}:{1}]'.format(*config['yrange']),
    ])
    datasets = ', '.join(source['data'] for source in config['sources'])
    return ' | '.join([config['title'], ranges, datasets])


def main():
    config = {
        'terminal': 'pngcairo',
        'size': '800,600',
        'output': 'temperature.png',
        'title': 'Daily Temperature',
        'xlabel': 'Hour',
        'ylabel': 'Degrees C',
        'xrange': ('0', '24'),
