        'sources': [
            {'data': 'indoor.dat', 'columns': (1, 2)},
            {'data': 'outdoor.dat', 'columns': (1, 3)},
        ],
    }
    print(describe_config(config))
    print(build_script(config))
    print(gnuplot_xrange('0', '10'))


if __name__ == '__main__':
