        gnuplot_ylabel(config['ylabel']),
        gnuplot_xrange(config['xrange'][0], config['xrange'][1]),
        gnuplot_yrange(config['yrange'][0], config['yrange'][1]),
    ]
    for source in config['sources']:
        commands.append(gnuplot_plot(source['data'], using_spec(source['columns'])))
    result = ''
