    return ''.join(['reject ', _quote(reason), ';'])


def sieve_addflag(flag):
    return ''.join(['addflag ', _quote(flag), ';'])


def sieve_setflag(flag):
    return ''.join(['setflag ', _quote(flag), ';'])


