def _attributes(pairs):
    return ' '.join(['{}="{}"'.format(key, value) for key, value in pairs])


def wl_interface(name, ver):
    return ''.join(['<interface ', _attributes([('name', name), ('version', ver)]), '>'])


def wl_request(name):
    return ''.join(['<request ', _attributes([('name', name)]), '>'])


def wl_event(name):
    return ''.join(['<event ', _attributes([('name', name)]), '>'])


def wl_arg(name, arg_type):
    return ''.join(['<arg ', _attributes([('name', name), ('type', arg_type)]), '/>'])


def wl_arg_summary(name, arg_type, summary):
    pairs = [('name', name), ('type', arg_type), ('summary', summary)]
    return ''.join(['<arg ', _attributes(pairs), '/>'])


def wl_enum(name):
    return ''.join(['<enum ', _attributes([('name', name)]), '>'])


def wl_entry(name, val, summary):
    pairs = [('name', name), ('value', val), ('summary', summary)]
    return ''.join(['<entry ', _attributes(pairs), '/>'])


def wl_description(summary):
    return ''.join(['<description ', _attributes([('summary', summary)]), '/>'])


def indent(level, element):
    return ''.join(['  ' * level, element])


def request_block(level, name, summary, args):
    lines = [indent(level, wl_request(name)), indent(level + 1, wl_description(summary))]
    for arg_name, arg_type, arg_summary in args:
        lines.append(indent(level + 1, wl_arg_summary(arg_name, arg_type, arg_summary)))
    lines.append(indent(level, '</request>'))
    return '\n'.join(lines)


def enum_block(level, name, entries):
    lines = [indent(level, wl_enum(name))]
    for entry_name, value, summary in entries:
        lines.append(indent(level + 1, wl_entry(entry_name, value, summary)))
    lines.append(indent(level, '</enum>'))
    return '\n'.join(lines)


