def format_location(volume, reporter, page):
    return ' '.join([volume, reporter, page])


def format_jurisdiction(jurisdiction, state, year):
    return ' '.join([jurisdiction, state, year])


def format_publication(author, article, journal):
    return ', '.join([author, article, journal])


def _validate(record, index):
    if len(record) != 12:
        raise ValueError(''.join([
            'record ', str(index), ' must have 12 fields, got ', str(len(record))]))
    for position, field in enumerate(record):
        if not isinstance(field, str):
            raise TypeError('-'.join([
                'record ' + str(index), 'field ' + str(position), 'expected str']))


def cite(records):
    citations = []
    for index, record in enumerate(records):
        _validate(record, index)
        (plaintiff, respondent, court, volume, reporter, page,
         jurisdiction, state, year, author, article, journal) = record
        citations.append((
            format_parties(plaintiff, respondent, court),
            format_location(volume, reporter, page),
            format_jurisdiction(jurisdiction, state, year),
            format_publication(author, article, journal),
            '-'.join([plaintiff, year]),
            '-'.join([respondent, court]),
            '/'.join([volume, author]),
            '/'.join([reporter, jurisdiction]),
        ))
    return citations


def render_citation(citation):
    return ' | '.join(citation)


def render_report(records):
    lines = []
    for index, citation in enumerate(cite(records)):
        lines.append(''.join(['Case ', str(index + 1), ': ', render_citation(citation)]))
    return '\n'.join(lines)


def main():
