def apparition(report):
    parts = [report.get('transparency', ''), report.get('shape', ''), report.get('aura', '')]
    return '-'.join([p for p in parts if p])

def poltergeist(report):
    parts = [report.get('movement', ''), report.get('noise', ''), report.get('damage', '')]
    return '/'.join([p for p in parts if p])

def evp(report):
    parts = [report.get('static', ''), report.get('voice', ''), report.get('message', '')]
    return ', '.join(p for p in parts if p)

def temperature(report):
    parts = [report.get('cold', ''), report.get('draft', ''), report.get('fluctuation', '')]
    return ':'.join([p for p in parts if p])

def emf(report):
    parts = [report.get('spike', ''), report.get('frequency', ''), report.get('duration', '')]
    return '.'.join([p for p in parts if p])

def possession(report):
    parts = [report.get('host', ''), report.get('symptom', ''), report.get('exorcism', '')]
    return '+'.join([p for p in parts if p])

def location(report):
    parts = [report.get('room', ''), report.get('furniture', ''), report.get('shadow', '')]
    return ' '.join([p for p in parts if p])

def equipment(report):
    parts = [report.get('camera', ''), report.get('battery', ''), report.get('glitch', '')]
    return '->'.join([p for p in parts if p])

def ghost(cases):
    sections = [
        ('APPARITION', apparition),
        ('POLTERGEIST', poltergeist),
        ('EVP', evp),
        ('TEMPERATURE', temperature),
        ('EMF', emf),
        ('POSSESSION', possession),
        ('LOCATION', location),
        ('EQUIPMENT', equipment),
    ]
    formatted = []
    for index, report in enumerate(cases, start=1):
        details = []
        for label, builder in sections:
            value = builder(report)
            if value:
                details.append(''.join([label, '=', value]))
        if details:
            body = ' | '.join(details)
        else:
            body = 'NO EVIDENCE'
        formatted.append(''.join(['CASE ', str(index), ': ', body]))
    return formatted

def main():
