DISCIPLINES = {
    'judo': judo_match,
    'karate': karate_match,
    'taekwondo': taekwondo_match,
    'boxing': boxing_match,
    'wrestling': wrestling_match,
    'muay thai': muay_thai_match,
    'jiu jitsu': jiu_jitsu_match,
    'capoeira': capoeira_match,
}


def bracket(matches):
    descriptions = []
    for fight in matches:
        handler = DISCIPLINES.get(fight.get('discipline'))
        if handler is None:
            descriptions.append('Unknown Discipline')
        else:
            descriptions.append(handler(fight))
    return descriptions


def card_lines(matches):
    lines = []
    for number, (fight, description) in enumerate(zip(matches, bracket(matches)), 1):
        label = ' '.join([str(number) + '.', fight.get('discipline', 'unknown').title()])
        lines.append(''.join([label.ljust(18), description]))
    return lines


