def format_guard_patrol(note):
    parts = [note.get('route', 'none'), note.get('timing', 'none'), note.get('shift', 'none')]
    return '-'.join(parts)

def format_vault_lock(note):
    parts = [note.get('tumbler', 'none'), note.get('dial', 'none'), note.get('timer', 'none')]
    return '/'.join(parts)

def format_alarm_system(note):
    parts = [note.get('wire', 'none'), note.get('sensor', 'none'), note.get('override', 'none')]
    return ':'.join(parts)

def format_getaway_vehicle(note):
    parts = [note.get('engine', 'none'), note.get('tire', 'none'), note.get('disguise', 'none')]
    return '.'.join(parts)

def format_disguise(note):
    parts = [note.get('uniform', 'none'), note.get('badge', 'none'), note.get('radio', 'none')]
    return '+'.join(parts)

def format_laser_grid(note):
    parts = [note.get('mirror', 'none'), note.get('smoke', 'none'), note.get('acrobatics', 'none')]
    return ', '.join(parts)

def format_safe_cracking(note):
    parts = [note.get('stethoscope', 'none'), note.get('drill', 'none'), note.get('explosive', 'none')]
    return ' '.join(parts)

def format_distraction(note):
    parts = [note.get('noise', 'none'), note.get('flare', 'none'), note.get('panic', 'none')]
    return '->'.join(parts)

def scheme(targets):
    instructions = []
    for note in targets:
        patrol = format_guard_patrol(note)
        vault = format_vault_lock(note)
        alarm = format_alarm_system(note)
        vehicle = format_getaway_vehicle(note)
        disguise = format_disguise(note)
        laser = format_laser_grid(note)
        safe = format_safe_cracking(note)
        distraction = format_distraction(note)

        compiled_parts = [patrol, vault, alarm, vehicle, disguise, laser, safe, distraction]
        full_instruction = ' | '.join(compiled_parts)
        instructions.append(full_instruction)

    return instructions

def _require(stats, keys):
    missing = [key for key in keys if not str(stats.get(key, '')).strip()]
    if missing:
        detail = ', '.join(missing)
        raise ValueError(''.join(['incomplete athlete stats, missing: ', detail]))
    return [str(stats[key]).strip() for key in keys]


