}


def sight(encounters):
    guide = []
    for report in encounters:
        creature = str(report.get('creature', '')).strip().lower()
        builder = BUILDERS.get(creature)
        if builder is None:
            guide.append(''.join(['Unknown creature: ', creature or '(unnamed)']))
            continue
        missing = [field for field in FIELDS[creature] if not report.get(field)]
        if missing:
            gaps = ', '.join(missing)
            guide.append(''.join([creature.title(), ': missing ', gaps]))
            continue
        guide.append(''.join([creature.title(), ': ', builder(report)]))
    return guide


