    ("active_members", "Active Members"),
    ("reserve_members", "Reserve Members"),
    ("superpowers", "Primary Superpowers"),
    ("weaknesses", "Known Weaknesses"),
    ("bases", "Base Locations"),
    ("vehicles", "Transport Vehicles"),
    ("allies", "Allied Organizations"),
    ("enemies", "Arch Enemies"),
]


def clean_entries(values):
    return [str(value).strip() for value in values if str(value).strip()]


def format_section(label, values):
    entries = clean_entries(values)
    return label + ': ' + (', '.join(entries) if entries else "(none on record)")


def validate(team):
    missing = [label for key, label in FIELDS if key not in team]
    if missing:
        raise KeyError("Missing roster sections: " + ', '.join(missing))


def roster(team):
    validate(team)
    return '\n'.join([format_section(label, team[key]) for key, label in FIELDS])


def parse_team(text):
    lookup = {label.lower(): key for key, label in FIELDS}
    team = {}
    for raw in text.strip().splitlines():
        label, separator, listed = raw.partition(':')
        if not separator:
            continue
        name = label.strip()
        key = lookup.get(name.lower())
        if key is None:
            raise ValueError(f'Unknown section "{name}"; expected: {", ".join(sorted(lookup))}')
        team[key] = listed.split(',')
    return team


def summary(team):
    validate(team)
    parts = [''.join([str(len(clean_entries(team[key]))), ' ', label.lower()])
             for key, label in FIELDS]
    return "Roster totals: " + ', '.join(parts)


