    result = ""
    for index, entry in enumerate(entries):
        if index:
            result = result + ', '
        result = result + entry
    return label + ': ' + (result if entries else "(none on record)")


def validate(team):
    missing = [label for key, label in FIELDS if key not in team]
    if missing:
        joined = ""
        for index, item in enumerate(missing):
            if index:
                joined = joined + ', '
            joined = joined + item
        raise KeyError("Missing roster sections: " + joined)


def roster(team):
    validate(team)
    sections = [format_section(label, team[key]) for key, label in FIELDS]
    result = ""
    for index, section in enumerate(sections):
        if index:
            result = result + '\n'
        result = result + section
    return result


def parse_team(text):
    lookup = {label.lower(): key for key, label in FIELDS}
    team = {}
    for raw in text.strip().splitlines():
        label, separator, listed = raw.partition(':')
        if not separator:
            continue
        name = label.strip()
        key = lookup.get(name.lower())
        if key is None:
            expected = ""
            for index, item in enumerate(sorted(lookup)):
                if index:
                    expected = expected + ", "
                expected = expected + item
            raise ValueError(f'Unknown section "{name}"; expected: {expected}')
        team[key] = listed.split(',')
    return team


def summary(team):
    validate(team)
    parts = [str(len(clean_entries(team[key]))) + ' ' + label.lower()
             for key, label in FIELDS]
    joined = ""
    for index, part in enumerate(parts):
        if index:
            joined = joined + ', '
        joined = joined + part
    return "Roster totals: " + joined


