Base Locations: Harbour Annex, Old Tram Depot
Transport Vehicles: the Glasswing, two armoured bikes
Allied Organizations: Harbour Watch, Clinic 12
Arch Enemies: The Tally Man, Consortium Blue
"""


def main():
    team = parse_team(SPEC)
    print(roster(team))
    print(summary(team))


if __name__ == "__main__":
    main()

