REQUIRED_FIELDS = ('name', 'sol', 'battery', 'waypoints', 'instruments')


def _validate(rover):
    missing = [field for field in REQUIRED_FIELDS if field not in rover]
    if missing:
        detail = ', '.join(missing)
        raise ValueError(''.join(['rover record is missing: ', detail]))
    if len(rover['waypoints']) < 2:
        raise ValueError('a daily plan needs at least two waypoints')


def target_coordinates(rover):
    marks = []
    for x, y in rover['waypoints']:
        marks.append(''.join(['(', str(x), '/', str(y), ')']))
    return '-'.join(marks)


def camera_angles(rover):
    shots = []
    for x, y in rover['waypoints']:
        shots.append(''.join(['pan ', str((x * 15) % 360), ' tilt ', str((y * 5) % 45)]))
    return ', '.join(shots)


def _drill_points(rover):
    return [(x, y) for x, y in rover['waypoints'] if (x + y) % 2 == 0]


def drill_sites(rover):
    sites = []
    for index, (x, y) in enumerate(_drill_points(rover), start=1):
        sites.append(''.join(['D', str(index), '@', str(x), '/', str(y)]))
    return ', '.join(sites)


def sample_types(rover):
    kinds = ['regolith', 'basalt chip', 'ice core', 'dust film']
    picks = [kinds[(x + y) % len(kinds)] for x, y in _drill_points(rover)]
    return ', '.join(picks)


def drive_paths(rover):
    points = rover['waypoints']
    legs = []
    for start, end in zip(points, points[1:]):
        distance = abs(start[0] - end[0]) + abs(start[1] - end[1])
        legs.append(''.join(['leg ', str(distance), 'm']))
    return '-'.join(legs)


def power_levels(rover):
    tasks = ['drive', 'drill', 'comms', 'heaters']
    shares = [40, 25, 20, 15]
    readings = [''.join([t, ' ', str(rover['battery'] * s // 100), '%']) for t, s in zip(tasks, shares)]
    return ', '.join(readings)


def antenna_alignments(rover):
    windows = []
    for slot in range(3):
        azimuth = (rover['sol'] * 7 + slot * 45) % 360
        windows.append(''.join(['win', str(slot + 1), ' az ', str(azimuth)]))
    return ', '.join(windows)


def sleep_cycles(rover):
    cycles = []
    hour = 22
    for instrument in rover['instruments']:
        nap_end = (hour + 2) % 24
        clock = ''.join([str(hour).zfill(2), ':00-', str(nap_end).zfill(2), ':00'])
        cycles.append(''.join([instrument, ' idle ', clock]))
        hour = nap_end
    return ', '.join(cycles)


def mission(rover):
    _validate(rover)
    sections = [
        ('Target Coordinates', target_coordinates(rover)),
        ('Camera Angles', camera_angles(rover)),
        ('Drill Sites', drill_sites(rover)),
        ('Sample Types', sample_types(rover)),
        ('Drive Paths', drive_paths(rover)),
        ('Power Levels', power_levels(rover)),
        ('Antenna Alignments', antenna_alignments(rover)),
        ('Sleep Cycles', sleep_cycles(rover)),
    ]
    header = ''.join([rover['name'], ' sol ', str(rover['sol']), ' operation plan'])
    lines = [''.join([label, ': ', body]) for label, body in sections]
    return '\n'.join([header] + lines)


