        'zones': ['front stalls', 'center rows', 'balcony', 'accessible bay'],
        'exits': ['north corridor', 'east stairwell', 'lobby doors'],
    }
    riverside = dict(downtown, movies=['Winter Signal'], trailers=[], late=['8:05', '10:20'])
    print(daily_digest([downtown, riverside]))


if __name__ == '__main__':
