    lines = []
    name = str(area.get('name', '')).strip()
    if name:
        lines.append(''.join(['AREA: ', name.upper()]))
    for key, heading in TOPICS:
        lines.append(format_line(heading, clean_items(area.get(key))))
    return '\n'.join(lines)


def missing_topics(area):
    return [heading for key, heading in TOPICS if not clean_items(area.get(key))]


def inventory_summary(area):
    parts = []
    for key, heading in TOPICS:
        count = len(clean_items(area.get(key)))
        parts.append(''.join([heading.title(), ' x', str(count)]))
    tally = ', '.join(parts)
    return ''.join(['TALLY: ', tally])


def readiness_report(area):
    gaps = missing_topics(area)
    if gaps:
        listed = ', '.join(gaps)
        return ''.join(['STATUS: INCOMPLETE - no data for ', listed])
    total = sum(len(clean_items(area.get(key))) for key, _ in TOPICS)
    return ''.join(['STATUS: READY - ', str(total), ' entries catalogued'])


