"""Build the printed visitor guide for a marine biology exhibit."""

PREFIXES = [
    ('tank_names', 'Tanks'),
    ('fish_species', 'Fish species'),
    ('coral_types', 'Coral types'),
    ('feeding_times', 'Feeding times'),
    ('water_parameters', 'Water parameters'),
    ('private_donors', 'Private donors'),
    ('conservation_messages', 'Conservation notes'),
    ('restricted_areas', 'Restricted areas'),
]

FEEDING_KEY = 'feeding_times'


def _clean(values):
    """Return the non-empty, trimmed entries of one guide category."""
    if isinstance(values, str):
        values = [values]
    return [str(value).strip() for value in values if str(value).strip()]


def _series(values):
    res = ''
    for i, s in enumerate(_clean(values)):
        res += (', ' if i else '') + s
    return res


def _schedule(values):
    res = ''
    for i, s in enumerate(_clean(values)):
        res += (' & ' if i else '') + s
    return res


def _line(prefix, body):
    return prefix + ': ' + (body or 'none listed')


def _check_categories(aquarium):
    known = {key for key, _ in PREFIXES}
    unknown = sorted(set(aquarium) - known)
    if unknown:
        listed = ''
        for i, s in enumerate(unknown):
            listed += (', ' if i else '') + s
        raise KeyError('unknown exhibit categories: ' + listed)


def exhibit(aquarium):
    """Return the guide text, one labelled category per line."""
    if not isinstance(aquarium, dict):
        raise TypeError('aquarium must be a mapping of category names to lists')
    _check_categories(aquarium)
    lines = []
    for key, prefix in PREFIXES:
        values = aquarium.get(key, [])
        if key == FEEDING_KEY:
            body = _schedule(values)
        else:
            body = _series(values)
        lines.append(_line(prefix, body))
    res = ''
    for i, s in enumerate(lines):
        res += ('\n' if i else '') + s
    return res


def main():
    aquarium = {
        'tank_names': ['Kelp Forest', 'Open Sea', 'Tide Pool'],
        'fish_species': ['garibaldi', 'moon jelly', 'leopard shark'],
        'coral_types': ['staghorn', 'brain', 'soft sea fan'],
        'feeding_times': ['10:30', '13:00', '15:45'],
        'water_parameters': ['salinity 34 ppt', 'pH 8.1', '17 C'],
        'private_donors': ['Reyes Family Trust', 'Blue Horizon Fund'],
        'conservation_messages': ['Choose sustainable seafood', 'Refuse single-use plastic'],
        'restricted_areas': ['quarantine lab', 'pump gallery'],
    }
    print(exhibit(aquarium))


if __name__ == '__main__':
    main()

