    numerology = '='.join([str(draw['number']), draw['meaning']])
    position = '-'.join([draw['phase'], draw['aspect']])
    timing = '~'.join([draw['season'], draw['duration']])
    return ', '.join([orientation, element, numerology, position, timing])


def tarot(session):
    return '; '.join(draw_summary(draw) for draw in session)


def archive(sessions):
    return '\n\n'.join(tarot(session) for session in sessions)


