FIELDS = (
    'heading', 'pace', 'left', 'right', 'tiles', 'traps',
    'height', 'features', 'source', 'brightness', 'echo', 'origin',
)


def _concat(parts, separator):
    text = ''
    for position, part in enumerate(parts):
        if position:
            text = text + separator
        text = text + part
    return text


def _validate(step, index):
    missing = [key for key in FIELDS if key not in step]
    if missing:
        detail = _concat(missing, ', ')
        raise KeyError(''.join(['step ', str(index), ' is missing: ', detail]))


def movement_string(step):
    return '_'.join([step['heading'], step['pace']])


def wall_string(step):
    return ':'.join([step['left'], step['right']])


def floor_string(step):
    return '+'.join([step['tiles'], step['traps']])


def ceiling_string(step):
    return '-'.join([step['height'], step['features']])


def lighting_string(step):
    return '_'.join([step['source'], step['brightness']])


def sound_string(step):
    return '_'.join([step['echo'], step['origin']])


def waypoint_string(step, index):
    _validate(step, index)
    elements = [
        movement_string(step), wall_string(step), floor_string(step),
        ceiling_string(step), lighting_string(step), sound_string(step),
    ]
    return '-'.join(elements)


def journey_segment_string(steps, offset):
    waypoints = [waypoint_string(step, offset + i) for i, step in enumerate(steps)]
    return _concat(waypoints, ',')


def _segments(maze):
    if maze and isinstance(maze[0], dict):
        return [list(maze)]
    return [list(segment) for segment in maze]


def navigate(maze):
    rendered = []
    offset = 0
    for segment in _segments(maze):
        rendered.append(journey_segment_string(segment, offset))
        offset += len(segment)
    return _concat(rendered, '||')


def describe(maze):
    lines = []
    for number, segment in enumerate(_segments(maze), 1):
        headings = _concat([step['heading'] for step in segment], ', ')
        lines.append(''.join(['segment ', str(number), ': ', str(len(segment)),
                              ' waypoint(s) heading ', headings]))
    return _concat(lines, '\n')


def main():
    first = {
        'heading': 'north', 'pace': 'five', 'left': 'stone', 'right': 'stone',
        'tiles': 'pit', 'traps': 'none', 'height': 'ten', 'features': 'tall',
