)


def _concat(parts, delimiter):
    """Chain the given parts together, placing the delimiter between them."""
    text = parts[0]
    for part in parts[1:]:
        text = text + delimiter + part
    return text


def _validate_delimiters(delimiters):
    if len(delimiters) != 8:
        raise ValueError(''.join(['expected 8 delimiters, got ', str(len(delimiters))]))
    for position, delimiter in enumerate(delimiters):
        if not isinstance(delimiter, str):
            raise TypeError(''.join(['delimiter ', str(position), ' is not a string']))


def _validate_model(index, model):
    if len(model) != 7:
        raise ValueError(''.join(['model ', str(index), ': expected 7 groups, got ', str(len(model))]))
    for name, group in zip(SEGMENT_NAMES, model):
        if len(group) != 3:
            raise ValueError(''.join(
                ['model ', str(index), ': ', name, ' has ', str(len(group)), ' entries instead of 3']))


def describe_layout(delimiters):
    """Report which delimiter joins which segment of a specification."""
    return [''.join([name, ' -> ', repr(d)]) for name, d in zip(SEGMENT_NAMES, delimiters)]


def assemble_segments(model, delimiters):
    """Combine each of the seven groups of a model with its matching delimiter."""
    return [_concat(group, delim) for group, delim in zip(model, delimiters[:7])]


def build_production_specs(models, delimiters):
    _validate_delimiters(delimiters)
    specs = []
    for index, model in enumerate(models):
        _validate_model(index, model)
        specs.append(_concat(assemble_segments(model, delimiters), delimiters[7]))
    return specs


def format_report(specs):
    lines = []
    for number, spec in enumerate(specs, start=1):
        lines.append(''.join(['Model ', str(number).zfill(2), ': ', spec]))
    return lines


