def join_series(items, separator):
    """Join a series of manifest entries, or report an empty series."""
    if not items:
        return '(none)'
    out = items[0]
    for item in items[1:]:
        out = out + separator + item
    return out


def check_flight(flight, index):
    """Reject a flight record that does not carry all six required fields."""
    if len(flight) != 6:
        raise ValueError('Flight ' + str(index) + ' needs exactly 6 fields')
    pilot, color = flight[0], flight[1]
    if not pilot or not color:
        raise ValueError('Flight ' + str(index) + ' is missing pilot or colour')


def profile_line(pilot, color):
    return pilot + ': ' + color


def passenger_line(passengers):
    names = join_series(passengers, ', ')
    return 'Passengers: ' + names


def cargo_line(cargo):
    items = join_series(cargo, '-')
    return 'Cargo: ' + items


def weather_line(conditions):
    readings = join_series(conditions, '~')
    return 'Weather:' + ' ' + readings


def landing_line(zones):
    places = join_series(zones, '/')
    return 'Landing zones:' + ' ' + places


def pilot_summary(pilot, passengers):
    count = str(len(passengers))
    noun = 'passenger' if len(passengers) == 1 else 'passengers'
    return 'Pilot' + ' ' + pilot + ' ' + 'carries' + ' ' + count + ' ' + noun + '.'


def flight_block(flight):
    pilot, color, passengers, cargo, conditions, zones = flight
    parts = [
        profile_line(pilot, color),
        passenger_line(passengers),
        cargo_line(cargo),
        weather_line(conditions),
        landing_line(zones),
        pilot_summary(pilot, passengers),
    ]
    return join_series(parts, '\n')


def manifest(flights):
    header = '====' + ' ' + 'BALLOON FLIGHT MANIFEST' + ' ' + '===='
    blocks = []
    for index, flight in enumerate(flights, start=1):
        check_flight(flight, index)
        label = 'Flight #' + str(index)
        blocks.append(join_series([label, flight_block(flight)], '\n'))
    if blocks:
        body = join_series(blocks, '\n\n')
    else:
        body = 'No flights scheduled.'
    footer = 'Thank you to all' + ' ' + 'balloon crews!'
    return join_series([header, body, footer], '\n\n')


def main():
    flights = [
        ('John', 'red', ['Alice', 'Bob'], ['propane', 'water'],
         ['sunny', 'calm'], ['field', 'park']),
    ]
    print(manifest(flights))


if __name__ == '__main__':
    main()

