def format_character_header(name, wood):
    return ' - '.join([name.title(), wood.lower()])


def format_strings(heads, arms, legs, details):
    head_text = ', '.join(heads)
    arm_text = ': '.join(arms)
    leg_text = '='.join(legs)
    detail_text = '/'.join(details)
    return [
        ''.join(['  Head strings: ', head_text]),
        ''.join(['  Arm strings: ', arm_text]),
        ''.join(['  Leg strings: ', leg_text]),
        ''.join(['  Painted details: ', detail_text]),
    ]


def summarize_puppet(name, total):
    return ''.join([
        '  ', name.title(), ' is controlled by ', str(total),
        ' strings in total.',
    ])


def validate(puppet):
    if len(puppet) != 6:
        raise ValueError(''.join([
            'each puppet needs 6 fields, got ', str(len(puppet)),
        ]))
    name, wood = puppet[0], puppet[1]
    if not name or not wood:
        raise ValueError('a puppet needs both a name and a wood type')
    empty = [label for label, parts in zip(
        ['heads', 'arms', 'legs', 'details'], puppet[2:]) if not parts]
    if empty:
        missing = ', '.join(empty)
        raise ValueError(''.join([name, ' is missing: ', missing]))


def rig(puppets):
    manual = ['RIGGING INSTRUCTIONS FOR THE MARIONETTE WORKSHOP', '']
    for puppet in puppets:
        validate(puppet)
        name, wood, heads, arms, legs, details = puppet
        manual.append(format_character_header(name, wood))
        manual.extend(format_strings(heads, arms, legs, details))
        manual.append(summarize_puppet(name, len(heads) + len(arms) + len(legs)))
        manual.append('')
    names = ', '.join([p[0].title() for p in puppets])
    manual.append(' '.join(['Backstage sign off:', names, 'are ready to walk.']))
    return '\n'.join(manual)


def main():
    puppets = [
        ('pinocchio', 'pine',
         ['left ear', 'right ear'],
         ['left wrist', 'right wrist'],
         ['left knee', 'right knee'],
         ['red cheeks', 'blue eyes']),
        ('columbine', 'maple',
         ['crown', 'chin'],
         ['left elbow', 'right elbow'],
         ['left ankle', 'right ankle'],
         ['gold mask']),
    ]
    print(rig(puppets))
    try:
        rig([('harlequin', 'oak', [], ['left wrist'], ['left knee'], [])])
    except ValueError as error:
        print(': '.join(['Rigging aborted', str(error)]))


if __name__ == '__main__':
    main()

