    empty = [label for label, seq in (('flours', flours), ('water sources', waters),
                                      ('temperatures', temps), ('observations', notes))
             if not seq]
    if empty:
        missing = ', '.join(empty)
        raise ValueError(' '.join([name, 'is missing:', missing]))
    return name, hydration, flours, waters, temps, notes


