    result = ''
    for i, part in enumerate(temps):
        if i:
            result = result + '-'
        result = result + part
    return result


def format_observations(notes):
    result = ''
    for i, part in enumerate(notes):
        if i:
            result = result + '; '
        result = result + part
    return result


def summarize(name, flours):
    return name + ' is fed with ' + str(len(flours)) + ' flour type(s).'


def describe_starter(entry):
    name, hydration, flours, waters, temps, notes = entry
    lines = [
        format_identity(name, hydration),
        '  Flours: ' + format_flours(flours),
        '  Water: ' + format_water(waters),
        '  Temperatures: ' + format_temps(temps),
        '  Observations: ' + format_observations(notes),
        '  ' + summarize(name, flours),
    ]
    result = ''
    for i, part in enumerate(lines):
        if i:
            result = result + '\n'
        result = result + part
    return result


def validate(entry):
    if len(entry) != 6:
        raise ValueError('each starter needs 6 fields')
    name, hydration, flours, waters, temps, notes = entry
    empty = [label for label, seq in (('flours', flours), ('water sources', waters),
                                      ('temperatures', temps), ('observations', notes))
             if not seq]
    if empty:
        missing = ''
        for i, part in enumerate(empty):
            if i:
                missing = missing + ', '
            missing = missing + part
        raise ValueError(name + ' ' + 'is missing:' + ' ' + missing)
    return name, hydration, flours, waters, temps, notes


def feed(starters):
    blocks = ['DAILY SOURDOUGH FEEDING SCHEDULE']
    for entry in starters:
        blocks.append(describe_starter(validate(entry)))
    names = ''
    for i, part in enumerate([entry[0] for entry in starters]):
        if i:
            names = names + ', '
        names = names + part
    blocks.append('Prepare the bench for baking: ' + names + '.')
    result = ''
    for i, part in enumerate(blocks):
        if i:
            result = result + '\n'
        result = result + part
    return result


def main():
    starters = [
        ('dough boy', '100%', ['rye', 'wheat'], ['tap', 'filtered'],
