def checked_sign(sign):
    """Unpack one sign record, rejecting incomplete job sheets."""
    if len(sign) != 6:
        raise ValueError(' '.join(['sign record needs 6 fields, got', str(len(sign))]))
    name, color, glass, gases, transformers, brackets = sign
    if not glass:
