    return ''.join(['  Glass lengths: ', tubes])


def gas_line(gases):
    fills = ':'.join(gases)
    return ''.join(['  Gas fills: ', fills])


def transformer_line(transformers):
    supplies = '+'.join(transformers)
    return ''.join(['  Transformers: ', supplies])


def bracket_line(brackets):
    hardware = '|'.join(brackets)
    return ''.join(['  Brackets: ', hardware])


def sign_summary(name, glass_count):
    counted = ' '.join([str(glass_count), 'glass lengths'])
    return ''.join(['  Summary: the ', name, ' sign is built from ', counted, '.'])


