FIELD_NAMES = [
    'tube lengths', 'joint angles', 'braze locations', 'cable routes',
    'fork dimensions', 'bracket standards', 'tire clearances', 'paint layers',
]


def _texts(values):
    return [str(value) for value in values]


def _validate(frame, index):
    if len(frame) != 8:
        found = str(len(frame))
        raise ValueError('Frame ' + str(index) + ' needs 8 sections, found ' + found)
    bad = [name for name, part in zip(FIELD_NAMES, frame)
           if not isinstance(part, (list, tuple))]
    if bad:
        detail = ''
        for _i, _p in enumerate(bad):
            if _i:
                detail += ', '
            detail += _p
        raise ValueError('Frame ' + str(index) + ' has non-list sections: ' + detail)


def format_tubing(tube_lengths, joint_angles, fork_dimensions):
    lengths = ''
    for _i, _p in enumerate(_texts(tube_lengths)):
        if _i:
            lengths += ', '
        lengths += _p
    angles = ''
    for _i, _p in enumerate(_texts(joint_angles)):
        if _i:
            angles += '-'
        angles += _p
    forks = ''
    for _i, _p in enumerate(_texts(fork_dimensions)):
        if _i:
            forks += ';'
        forks += _p
    return [
        'Tube lengths: ' + lengths,
        'Joint angles: ' + angles,
        'Fork dimensions: ' + forks,
    ]


def format_fittings(braze_locations, cable_routes, bracket_standards):
    brazes = ''
    for _i, _p in enumerate(_texts(braze_locations)):
        if _i:
            brazes += '/'
        brazes += _p
    cables = ''
    for _i, _p in enumerate(_texts(cable_routes)):
        if _i:
            cables += ' '
        cables += _p
    brackets = ''
    for _i, _p in enumerate(_texts(bracket_standards)):
        if _i:
            brackets += '|'
        brackets += _p
    return [
        'Braze locations: ' + brazes,
        'Cable routes: ' + cables,
        'Bracket standards: ' + brackets,
    ]


def format_finishes(tire_clearances, paint_layers):
    tires = ''
    for _i, _p in enumerate(_texts(tire_clearances)):
        if _i:
            tires += '*'
        tires += _p
    paints = ''
    for _i, _p in enumerate(_texts(paint_layers)):
        if _i:
            paints += '_'
        paints += _p
    return [
        'Tire clearances: ' + tires,
        'Paint layers: ' + paints,
    ]


def export(frames):
    summaries = []
    for index, frame in enumerate(frames, start=1):
        _validate(frame, index)
        sections = format_tubing(frame[0], frame[1], frame[4])
        sections.extend(format_fittings(frame[2], frame[3], frame[5]))
        sections.extend(format_finishes(frame[6], frame[7]))
        body = ''
        for _i, _p in enumerate(sections):
            if _i:
                body += '\n  '
            body += _p
        summaries.append('Frame ' + str(index) + '\n  ' + body)
    return summaries


