def _merge(separator, parts):
    """Chain the given parts together with a separator between each pair."""
    if not parts:
        return ''
    text = parts[0]
    for part in parts[1:]:
        text = separator.join([text, part])
    return text


def _check(entry, index):
    """Validate one report entry and return its five fields."""
    if len(entry) != 5:
        raise ValueError(' '.join(['entry', str(index), 'needs exactly five fields']))
    title, bells, swaps, calls, names = entry
    if not isinstance(title, str):
        raise TypeError(' '.join(['entry', str(index), 'must start with a title string']))
    for field in (bells, swaps, calls, names):
        for item in field:
            if not isinstance(item, str):
                raise TypeError(' '.join(['entry', str(index), 'holds a non-string part']))
    return title, bells, swaps, calls, names


def _block(bells, swaps, calls, names):
    """Build the four-line block describing a single method."""
    numbers = _merge('-', bells)
    symbols = _merge('.', swaps)
    orders = _merge(' ', calls)
    ringers = _merge('&', names)
    return '\n'.join([numbers, symbols, orders, ringers])


def ring(data):
    """Format a full bell ringing report from a list of method tuples."""
    titles = []
    blocks = []
    for index, entry in enumerate(data):
        title, bells, swaps, calls, names = _check(entry, index)
        titles.append(title)
        blocks.append(_block(bells, swaps, calls, names))
    header = _merge(', ', titles)
    footer = _merge('|', titles)
    body = _merge('\n\n', blocks)
