FIELD_NAMES = ['rhythm name', 'hand strikes', 'rest counts', 'vocal chants', 'dynamic markings']


def _check_session(index, session):
    """Raise a descriptive error when a session tuple is malformed."""
    if len(session) != 5:
        expected = ', '.join(FIELD_NAMES)
        raise ValueError(''.join(['session ', str(index), ' must hold: ', expected]))
    empty = [FIELD_NAMES[pos] for pos in range(1, 5) if not session[pos]]
    if empty:
        listed = ', '.join(empty)
        raise ValueError(''.join(['session ', str(index), ' has no ', listed]))


def _format_block(session):
    """Turn one session tuple into its four-line performance block."""
    _name, strikes, rests, chants, dynamics = session
    strike_line = '-'.join(str(item) for item in strikes)
    rest_line = ' '.join(str(item) for item in rests)
    chant_line = '/'.join(str(item) for item in chants)
    dynamic_line = '+'.join(str(item) for item in dynamics)
    return '\n'.join([strike_line, rest_line, chant_line, dynamic_line])


def drum(sessions):
    """Format the full performance chart for a list of session tuples."""
    for index, session in enumerate(sessions):
        _check_session(index, session)
    names = [str(session[0]) for session in sessions]
