    """Build the value string from magnitude and unit, e.g. '10' + 'kOhm'."""
    return ''.join([str(component['magnitude']), component['unit']])


def format_nodes(component):
    """Wiring nodes of one component, separated by single spaces."""
    return ' '.join(str(node) for node in component['nodes'])


