    """One netlist line: identifier, value and node list."""
    return ' '.join([
        format_identifier(component),
        format_value(component),
        format_nodes(component),
    ])


def validate(components):
    """Reject components with missing fields or fewer than two nodes."""
    problems = []
    for index, component in enumerate(components):
        missing = [field for field in REQUIRED_FIELDS if field not in component]
        if missing:
            problems.append('component %d lacks %s' % (index, ', '.join(missing)))
        elif len(component['nodes']) < 2:
            problems.append('%s has too few nodes' % format_identifier(component))
