FIELDS = ('name', 'attribute', 'coordinate', 'target', 'color', 'sound', 'zone')


def normalize(component):
    """Return a component as a dict of seven stripped string fields."""
    if isinstance(component, dict):
        missing = [field for field in FIELDS if field not in component]
        if missing:
            detail = ', '.join(missing)
            raise ValueError('component is missing fields: ' + detail)
        return {field: str(component[field]).strip() for field in FIELDS}
    values = [str(value).strip() for value in component]
    if len(values) != len(FIELDS):
        expected = ', '.join(FIELDS)
        raise ValueError(''.join(['component needs exactly these fields: ', expected]))
    return dict(zip(FIELDS, values))


def parse_line(text):
    """Parse one comma separated component description."""
    return normalize(text.split(','))


def column(components, field):
    return [component[field] for component in components]


def flipper_row(components):
    return 'Flippers: ' + ' - '.join(column(components, 'name'))


