            for index, item in enumerate(missing):
                if index:
                    detail = detail + ', '
                detail = detail + item
            raise ValueError('component is missing fields: ' + detail)
        return {field: str(component[field]).strip() for field in FIELDS}
    values = [str(value).strip() for value in component]
    if len(values) != len(FIELDS):
        expected = ''
        for index, item in enumerate(FIELDS):
            if index:
                expected = expected + ', '
            expected = expected + item
        raise ValueError('component needs exactly these fields: ' + expected)
    return dict(zip(FIELDS, values))


def parse_line(text):
    """Parse one comma separated component description."""
    return normalize(text.split(','))


def column(components, field):
    return [component[field] for component in components]


def flipper_row(components):
    result = ''
    for index, item in enumerate(column(components, 'name')):
        if index:
            result = result + ' - '
        result = result + item
    return 'Flippers: ' + result


def bumper_row(components):
    result = ''
    for index, item in enumerate(column(components, 'attribute')):
        if index:
            result = result + ':'
        result = result + item
    return 'Bumpers: ' + result


def ramp_section(components):
    result = ''
    for index, item in enumerate(column(components, 'coordinate')):
        if index:
            result = result + ' -> '
        result = result + item
    return 'Ramps: ' + result


def target_bank(components):
    result = ''
    for index, item in enumerate(column(components, 'target')):
        if index:
            result = result + '|'
        result = result + item
    return 'Targets: ' + result


def lighting_array(components):
    result = ''
    for index, item in enumerate(column(components, 'color')):
        if index:
            result = result + ' + '
        result = result + item
    return 'Lighting: ' + result


def audio_array(components):
    result = ''
    for index, item in enumerate(column(components, 'sound')):
        if index:
            result = result + ' ~ '
        result = result + item
    return 'Audio: ' + result


def playfield_zones(components):
    result = ''
    for index, item in enumerate(column(components, 'zone')):
        if index:
            result = result + ' '
        result = result + item
    return 'Zones: ' + result


def blueprint(components):
    """Build the seven section text blueprint for the given components."""
    parts = [normalize(component) for component in components]
    sections = [
        flipper_row(parts),
        bumper_row(parts),
        ramp_section(parts),
        target_bank(parts),
        lighting_array(parts),
        audio_array(parts),
        playfield_zones(parts),
    ]
    result = ''
    for index, item in enumerate(sections):
        if index:
            result = result + '\n'
        result = result + item
    return result


def main():
    raw = [
        'LeftFlipper, rubber, 12x40, drop, red, thwack, lower',
        'SlingShot, elastic, 30x55, standup, amber, ping, middle',
        'LoopRamp, steel, 48x70, rollover, blue, whoosh, upper',
        'JackpotHole, magnet, 60x88, saucer, green, chime, backfield',
    ]
    components = [parse_line(line) for line in raw]
    print(blueprint(components))


if __name__ == '__main__':
    main()

