"""Assemble a printable manifest for a water slide tube run."""

CATEGORIES = ('straight', 'curve', 'drop', 'tunnel', 'splash', 'booster', 'pillar')

REQUIRED_FIELD = {'straight': 'length', 'curve': 'angle', 'drop': 'height',
                  'tunnel': 'color', 'splash': 'effect', 'booster': 'multiplier',
                  'pillar': 'material'}


def parse_segment(raw):
    kind = str(raw.get('kind', '')).strip().lower()
    if kind not in REQUIRED_FIELD:
        allowed = ', '.join(CATEGORIES)
        raise ValueError(' '.join(['unsupported segment kind', repr(kind), 'expected one of', allowed]))
    field = REQUIRED_FIELD[kind]
    if field not in raw:
        raise ValueError(' '.join([kind, 'segment is missing its', field]))
    segment = dict(raw)
    segment['kind'] = kind
    return segment


def straight_run(segments):
    body = ''
    for segment in segments:
        if segment['kind'] == 'straight':
            piece = ''.join([str(segment['length']), 'm'])
            body = piece if not body else '-'.join([body, piece])
    return ': '.join(['Straights', body or 'none'])


def curve_run(segments):
    body = ''
    for segment in segments:
        if segment['kind'] == 'curve':
            piece = ''.join([str(segment['angle']), 'deg'])
            body = piece if not body else ', '.join([body, piece])
    return ': '.join(['Curves', body or 'none'])


def drop_run(segments):
    body = ''
    for segment in segments:
        if segment['kind'] == 'drop':
            piece = ''.join([str(segment['height']), 'm'])
            body = piece if not body else ' -> '.join([body, piece])
    return ': '.join(['Drops', body or 'none'])


def tunnel_run(segments):
    body = ''
    for segment in segments:
        if segment['kind'] == 'tunnel':
            piece = str(segment['color'])
            body = piece if not body else ' + '.join([body, piece])
    return ': '.join(['Tunnels', body or 'none'])


def splash_run(segments):
    body = ''
    for segment in segments:
        if segment['kind'] == 'splash':
            piece = str(segment['effect'])
            body = piece if not body else ' ~ '.join([body, piece])
    return ': '.join(['Splash zones', body or 'none'])


def booster_run(segments):
    body = ''
    for segment in segments:
        if segment['kind'] == 'booster':
            piece = ''.join(['x', str(segment['multiplier'])])
            body = piece if not body else ' * '.join([body, piece])
    return ': '.join(['Boosters', body or 'none'])


def pillar_run(segments):
    body = ''
    for segment in segments:
        if segment['kind'] == 'pillar':
            piece = str(segment['material'])
            body = piece if not body else ' | '.join([body, piece])
    return ': '.join(['Pillars', body or 'none'])


def pipeline(segments):
    parsed = [parse_segment(raw) for raw in segments]
    straights = straight_run(parsed)
    curves = curve_run(parsed)
    drops = drop_run(parsed)
    tunnels = tunnel_run(parsed)
    splashes = splash_run(parsed)
    boosters = booster_run(parsed)
    pillars = pillar_run(parsed)
    return '; '.join([straights, curves, drops, tunnels, splashes, boosters, pillars])


