FIELDS = ("skill", "flip", "twist", "split", "pose", "step", "deduction")


def _validate(passes):
    if not passes:
        raise ValueError("at least one tumbling run is required")
    for index, run in enumerate(passes, start=1):
        for field in FIELDS:
            if field not in run:
                raise KeyError(''.join(["run ", str(index), " is missing '", field, "'"]))
            if not str(run[field]).strip():
                raise ValueError(''.join(["run ", str(index), " has an empty '", field, "'"]))


def _column(passes, field):
    return [str(run[field]).strip() for run in passes]


def _merge(values, separator):
    merged = values[0]
    for value in values[1:]:
        merged += separator
        merged += value
    return merged


def score(passes):
    """Return the seven-component routine shorthand for the given tumbling runs."""
    _validate(passes)
    forward = ''.join(["Forward tumbling: ", _merge(_column(passes, "skill"), "-")])
    backward = ''.join(["Backward tumbling: ", _merge(_column(passes, "flip"), "+")])
    twisting = ''.join(["Twisting sequence: ", _merge(_column(passes, "twist"), "/")])
    leaps = ''.join(["Leap series: ", _merge(_column(passes, "split"), ",")])
    balance = ''.join(["Balance elements: ", _merge(_column(passes, "pose"), ":")])
    dance = ''.join(["Dance sequence: ", _merge(_column(passes, "step"), "~")])
    landings = ''.join(["Landing deductions: ", _merge(_column(passes, "deduction"), "|")])
    return '\n\n'.join([forward, backward, twisting, leaps, balance, dance, landings])


def build_run(skill, flip, twist, split, pose, step, deduction):
    return dict(zip(FIELDS, (skill, flip, twist, split, pose, step, deduction)))


def report(gymnast, apparatus, passes):
    title = ' '.join([gymnast, "on", apparatus])
    header = ''.join(["=== ", title, " (", str(len(passes)), " runs) ==="])
    return '\n\n'.join([header, score(passes)])


def main():
