REQUIRED = ('grass', 'brick', 'speed', 'depth', 'incline', 'exit', 'width')


def parse_obstacle(text, index):
    """Turn 'grass=bent;brick=red;...' into a property dictionary."""
    obstacle = {}
    for field in text.split(';'):
        key, _, value = field.partition('=')
        obstacle[key.strip()] = value.strip()
    for key in REQUIRED:
        if key not in obstacle:
            raise ValueError(''.join(['obstacle ', str(index), ' lacks property ', key]))
    return obstacle


def _triple(obstacles, key):
    first, second, third = (obstacle[key] for obstacle in obstacles)
    return first, second, third


def surface_material(obstacles):
    first, second, third = _triple(obstacles, 'grass')
    grasses = ', '.join([first, second, third])
    return ''.join(['Surface material: ', grasses])


def boundary_wall(obstacles):
    first, second, third = _triple(obstacles, 'brick')
    bricks = '-'.join([first, second, third])
    return ''.join(['Boundary wall: ', bricks])


def windmill(obstacles):
    first, second, third = _triple(obstacles, 'speed')
    speeds = '+'.join([first, second, third])
    return ''.join(['Windmill: ', speeds])


def water_hazard(obstacles):
    first, second, third = _triple(obstacles, 'depth')
    depths = '/'.join([first, second, third])
    return ''.join(['Water hazard: ', depths])


def slope_elevation(obstacles):
    first, second, third = _triple(obstacles, 'incline')
    inclines = '>'.join([first, second, third])
    return ''.join(['Slope elevation: ', inclines])


def pipe_tunnel(obstacles):
    first, second, third = _triple(obstacles, 'exit')
    exits = ':'.join([first, second, third])
    return ''.join(['Pipe tunnel: ', exits])


def sand_trap(obstacles):
    first, second, third = _triple(obstacles, 'width')
    widths = '~'.join([first, second, third])
    return ''.join(['Sand trap: ', widths])


def minigolf(obstacles):
    if len(obstacles) != 3:
        raise ValueError(''.join(['a hole blueprint needs 3 obstacles, got ', str(len(obstacles))]))
    surface = surface_material(obstacles)
    wall = boundary_wall(obstacles)
    mill = windmill(obstacles)
    water = water_hazard(obstacles)
    slope = slope_elevation(obstacles)
    pipe = pipe_tunnel(obstacles)
    sand = sand_trap(obstacles)
    return '; '.join([surface, wall, mill, water, slope, pipe, sand])


def main():
    specs = [
        'grass=bent;brick=red;speed=slow;depth=shallow;incline=gentle;exit=left;width=narrow',
        'grass=fescue;brick=clinker;speed=medium;depth=knee;incline=steep;exit=center;width=wide',
        'grass=rye;brick=sandstone;speed=fast;depth=deep;incline=sheer;exit=right;width=broad',
    ]
    obstacles = [parse_obstacle(spec, index) for index, spec in enumerate(specs, 1)]
    print(minigolf(obstacles))


if __name__ == '__main__':
    main()

