FIELDS = ('color', 'pocket', 'path', 'spin', 'bridge', 'chalk', 'time')


def link(values, separator):
    """Concatenate an arbitrary number of values with the given separator."""
    chained = ''
    for position, value in enumerate(values):
        if position:
            chained += separator
        chained += value
    return chained


def field_values(shots, key):
    """Collect one detail from every shot, as text."""
    return [str(shot[key]) for shot in shots]


def validate(shots):
    """Reject shots that do not describe all seven details."""
    if not shots:
        raise ValueError('at least one shot is required')
    for number, shot in enumerate(shots, start=1):
        missing = [name for name in FIELDS if name not in shot]
        if missing:
            label = ' '.join(['Shot', str(number)])
            raise ValueError(': '.join([label, link(missing, ', ')]))


def snooker(shots):
    """Build the seven-line frame analysis document for a series of shots."""
    validate(shots)

    potted_line = ': '.join(['Potted balls', link(field_values(shots, 'color'), ',')])
    pocket_line = ': '.join(['Pocket selection', link(field_values(shots, 'pocket'), '-')])
    path_line = ': '.join(['Cue ball path', link(field_values(shots, 'path'), '>')])
    spin_line = ': '.join(['Spin application', link(field_values(shots, 'spin'), '+')])
    bridge_line = ': '.join(['Rest equipment', link(field_values(shots, 'bridge'), '/')])
    chalk_line = ': '.join(['Chalk usage', link(field_values(shots, 'chalk'), ':')])
    timing_line = ': '.join(['Shot timing', link(field_values(shots, 'time'), '~')])

    return '\n'.join([potted_line, pocket_line, path_line, spin_line,
                      bridge_line, chalk_line, timing_line])


