FIELDS = ("grab", "spin", "height", "stance", "wall", "carve", "spray")


def _as_maneuver(trick):
    """Normalise one maneuver into a dictionary keyed by the seven judged parts."""
    if isinstance(trick, dict):
        for field in FIELDS:
            if field not in trick:
                raise ValueError(": ".join(["Maneuver is missing field", field]))
        return {field: str(trick[field]) for field in FIELDS}
    parts = list(trick)
    if len(parts) != len(FIELDS):
        raise ValueError(" ".join(["A maneuver needs exactly seven entries:", str(FIELDS)]))
    return {field: str(value) for field, value in zip(FIELDS, parts)}


def halfpipe(tricks):
    """Build the seven-line judging shorthand sheet for a run of maneuvers."""
    runs = [_as_maneuver(trick) for trick in tricks]
    if not runs:
        raise ValueError("A run needs at least one maneuver")

    opener = runs[0]
    grabs = opener["grab"]
    spins = opener["spin"]
    heights = opener["height"]
    stances = opener["stance"]
    walls = opener["wall"]
    carves = opener["carve"]
    sprays = opener["spray"]

    for move in runs[1:]:
        grabs = ", ".join([grabs, move["grab"]])
        spins = "-".join([spins, move["spin"]])
        heights = "+".join([heights, move["height"]])
        stances = "/".join([stances, move["stance"]])
        walls = ":".join([walls, move["wall"]])
        carves = "~".join([carves, move["carve"]])
        sprays = "|".join([sprays, move["spray"]])

    return "\n".join([grabs, spins, heights, stances, walls, carves, sprays])


def render_sheet(rider, tricks):
    """Label a rider's shorthand sheet so judges can file it after the run."""
    heading = " ".join([rider, "-", "halfpipe shorthand"])
    return "\n".join([heading, halfpipe(tricks)])


