def caesar_cipher_encrypt(text, shift):
    """Shift alphabetic characters by `shift`, preserving case and other characters."""
    shift %= 26
    encrypted = []
    for ch in text:
        if ch.isalpha():
            base = ord('A') if ch.isupper() else ord('a')
            encrypted.append(chr(base + (ord(ch) - base + shift) % 26))
        else:
            encrypted.append(ch)
    return ''.join(encrypted)


def caesar_cipher_decrypt(text, shift):
    """Inverse of caesar_cipher_encrypt for the same shift."""
    return caesar_cipher_encrypt(text, -shift)


def shifted_alphabet(shift):
    """Return the lowercase alphabet as rewritten by the cipher, e.g. 'bcdefg...a'."""
    return ''.join([caesar_cipher_encrypt(chr(ord('a') + i), shift) for i in range(26)])


def format_mapping(shift):
    """Human readable letter mapping such as 'a->b, b->c, c->d ...'."""
    cipher = shifted_alphabet(shift)
    pairs = ['{0}->{1}'.format(chr(ord('a') + i), cipher[i]) for i in range(26)]
    return ', '.join(pairs)


def brute_force(text):
    """Return every possible decryption, as (shift, plaintext) pairs."""
    return [(shift, caesar_cipher_decrypt(text, shift)) for shift in range(26)]


def format_brute_force(text, limit=5):
    """Render the first `limit` brute force candidates, one per line."""
    lines = []
    for shift, candidate in brute_force(text)[:limit]:
        lines.append('  shift {0:2d}: {1}'.format(shift, candidate))
    return '\n'.join(lines)


def encrypt_words(text, shift):
    """Encrypt each whitespace separated word and rejoin them with single spaces."""
    return ' '.join(caesar_cipher_encrypt(word, shift) for word in text.split())


def report(text, shift):
    """Build a multi-line report about encrypting `text` with `shift`."""
    cipher = caesar_cipher_encrypt(text, shift)
    header = ''.join(['=== shift ', str(shift), ' ==='])
    details = [
        header,
        'plain    : {0}'.format(text),
        'cipher   : {0}'.format(cipher),
        'restored : {0}'.format(caesar_cipher_decrypt(cipher, shift)),
        'words    : {0}'.format(encrypt_words(text, shift)),
        'alphabet : {0}'.format(shifted_alphabet(shift)),
        'mapping  : {0}'.format(format_mapping(shift)),
    ]
    return '\n'.join(details)


def main():
    samples = [('abc', 1), ('xyz', 3), ('Hello, World!', 13), ('Attack at dawn', 5)]
    labels = ', '.join('{0!r}/{1}'.format(text, shift) for text, shift in samples)
    print('samples: ' + labels)
    for text, shift in samples:
        print(report(text, shift))
        print()
    secret = caesar_cipher_encrypt('Meet me at midnight', 7)
    print('brute forcing: ' + secret)
    print(format_brute_force(secret, limit=8))


if __name__ == '__main__':
    main()

