    reports = [compression_report(sample) for sample in samples]
    joined_reports = reports[0]
    for report in reports[1:]:
        joined_reports = joined_reports + '\n' + report
    print(joined_reports)
    print('-' * 60)
    longest = max(samples, key=lambda sample: max([c for _, c in group_runs(sample)] or [0]))
    print('longest run appears in %r -> %s' % (longest, run_length_encode(longest)))


