MONTH_LENGTHS = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)
WEEKDAYS = ('Thursday', 'Friday', 'Saturday', 'Sunday', 'Monday', 'Tuesday', 'Wednesday')


def is_leap(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def days_in_month(year, month):
    if month == 2 and is_leap(year):
        return 29
    return MONTH_LENGTHS[month - 1]


def parse_date(date_str):
    parts = date_str.split('-')
    if len(parts) != 3:
        raise ValueError(''.join(['expected YYYY-MM-DD, got ', repr(date_str)]))
    for part, width in zip(parts, (4, 2, 2)):
        if len(part) != width or not part.isdigit():
            raise ValueError(''.join(['malformed field ', repr(part), ' in ', date_str]))
    year, month, day = int(parts[0]), int(parts[1]), int(parts[2])
    if not 1 <= month <= 12:
        raise ValueError(''.join(['month out of range in ', date_str]))
    limit = days_in_month(year, month)
    if not 1 <= day <= limit:
        detail = ''.join([parts[0], '-', parts[1], ' has ', str(limit), ' days'])
        raise ValueError(', '.join(['day out of range', detail]))
    return year, month, day


def days_since_epoch(date_str):
    year, month, day = parse_date(date_str)
    shifted_year = year - (1 if month <= 2 else 0)
    era = (shifted_year if shifted_year >= 0 else shifted_year - 399) // 400
    year_of_era = shifted_year - era * 400
    day_of_year = (153 * (month + (-3 if month > 2 else 9)) + 2) // 5 + day - 1
    day_of_era = year_of_era * 365 + year_of_era // 4 - year_of_era // 100 + day_of_year
    return era * 146097 + day_of_era - 719468


def weekday_name(date_str):
    return WEEKDAYS[days_since_epoch(date_str) % 7]


def describe(date_str):
    count = days_since_epoch(date_str)
    unit = 'day' if abs(count) == 1 else 'days'
    return ''.join([date_str, ' -> ', str(count), ' ', unit, ' (', weekday_name(date_str), ')'])


def table_row(date_str):
    try:
        return ', '.join([date_str, str(days_since_epoch(date_str)), weekday_name(date_str)])
    except ValueError as err:
        return ', '.join([date_str, 'invalid', str(err)])


def main():
    samples = ['1970-01-01', '1970-01-02', '2000-02-29', '2024-12-31', '1969-07-20']
    for date_str in samples:
        print(describe(date_str))
    print()
    print(', '.join(['date', 'days_since_epoch', 'weekday']))
    for date_str in samples + ['2023-02-29', '2023-1-05']:
        print(table_row(date_str))


if __name__ == '__main__':
    main()

