        else:
            fail_msg_parts = ['Error', 'in', 'test', str(i+1)]
            print(' '.join(fail_msg_parts) + ': ' + result_str)

    footer_parts = ['Simulation', 'complete', 'for', 'all', 'tests']
    print(' '.join(footer_parts))

