def generate_permutations(lst):
    """Return a list of all orderings of the elements in lst."""
    if len(lst) <= 1:
        return [list(lst)]
    result = []
    for index, element in enumerate(lst):
        rest = lst[:index] + lst[index + 1:]
        for tail in generate_permutations(rest):
            result.append([element] + tail)
    return result


def format_permutation(perm):
    """Render a single permutation as a compact bracketed row."""
    items = ', '.join(str(item) for item in perm)
    return ''.join(['[', items, ']'])


def format_permutations(perms):
    """Render every permutation on its own numbered line."""
    width = len(str(len(perms)))
    lines = []
    for number, perm in enumerate(perms, start=1):
        label = str(number).rjust(width)
        lines.append(''.join([label, '. ', format_permutation(perm)]))
    return '\n'.join(lines)


def as_words(perms):
    """Join each permutation of single characters back into a word."""
    return [''.join([str(item) for item in perm]) for perm in perms]


def describe_input(lst):
    """Short human description of the list handed to the generator."""
    if not lst:
        return 'the empty list'
    names = sorted({type(item).__name__ for item in lst})
    kinds = ', '.join(names)
    return ''.join(['a list of ', str(len(lst)), ' element(s) of type ', kinds])


def report(lst):
    """Build a full textual report for the permutations of lst."""
    perms = generate_permutations(lst)
    sections = [
        ''.join(['Input:  ', format_permutation(lst)]),
        ''.join(['Detail: ', describe_input(lst)]),
        ''.join(['Count:  ', str(len(perms))]),
        format_permutations(perms),
    ]
    if lst and all(isinstance(item, str) and len(item) == 1 for item in lst):
        words = ', '.join(as_words(perms))
        sections.append(''.join(['Words:  ', words]))
    return '\n'.join(sections)


def main():
    samples = [[1, 2], ['a'], [], ['a', 'b', 'c'], [1, 2, 3, 4]]
    blocks = [report(sample) for sample in samples]
    print('\n\n'.join(blocks))
    counts = [str(len(generate_permutations(sample))) for sample in samples]
    totals = ' + '.join(counts)
    print(''.join(['\nPermutation counts: ', totals]))


if __name__ == '__main__':
    main()

