def extract_domain(url):
    parts = url.split('/')
    domain_part = ''
    for part in parts:
        if '.' in part:
            domain_part = part
            break

    if domain_part.startswith('www.'):
        domain_part = domain_part[4:]

    domain_segments = domain_part.split('.')
    if len(domain_segments) > 1:
        main_domain = domain_segments[0]
    else:
        main_domain = domain_part

    if '?' in main_domain:
        main_domain = main_domain.split('?')[0]

    return ''.join([s for s in main_domain if s.isalnum() or s == '-'])

