    return ''.join([
        expense['date'],
        '  ',
        expense['description'].ljust(20),
        '{:>10.2f}'.format(expense['amount']),
    ])


def monthly_totals(expenses):
    totals = {}
    for expense in expenses:
        month = expense['date'][:7]
        totals[month] = totals.get(month, 0.0) + expense['amount']
    return totals


