    lines = [''.join(['DATE'.ljust(12), 'DESCRIPTION'.ljust(20), 'AMOUNT'.rjust(10)])]
    for expense in sorted(expenses, key=lambda e: e['date']):
        lines.append(format_expense(expense))
    lines.append('-' * 42)
    summary = monthly_totals(expenses)
    for month in sorted(summary):
        lines.append(''.join([month, ' total: ', '{:.2f}'.format(summary[month])]))
    total = sum(expense['amount'] for expense in expenses)
    lines.append(''.join(['grand total: ', '{:.2f}'.format(total)]))
    return '\n'.join(lines)


