import sys

DIGITS = "0123456789"


def normalize(raw):
    """Remove surrounding and embedded whitespace from a raw zip code field."""
    return ''.join([ch for ch in raw if not ch.isspace()])


def is_valid_us_zip_code(zip_code):
    """Return True when zip_code is a string of exactly five digits."""
    if not isinstance(zip_code, str):
        return False
    if len(zip_code) != 5:
        return False
    return all(ch in DIGITS for ch in zip_code)


def describe_problems(zip_code):
    """Return a human readable explanation of why zip_code is rejected."""
    if not isinstance(zip_code, str):
        return "value is not a string"
    problems = []
    if len(zip_code) != 5:
        problems.append("expected 5 characters, got %d" % len(zip_code))
    bad = sorted({ch for ch in zip_code if ch not in DIGITS})
    if bad:
        problems.append("non-digit characters: " + ', '.join(repr(ch) for ch in bad))
    if not problems:
        return "valid"
    return '; '.join(problems)


def check_field(raw):
    """Validate one raw input field, tolerating stray whitespace."""
    cleaned = normalize(raw)
    return cleaned, is_valid_us_zip_code(cleaned)


def format_row(raw, cleaned, valid):
    cells = [
        repr(raw).ljust(14),
        cleaned.ljust(8),
        "OK" if valid else "FAIL",
        "" if valid else describe_problems(cleaned),
    ]
    return ' | '.join(cell for cell in cells if cell != "")


def build_report(raw_fields):
    lines = ["input          | cleaned  | status | detail"]
    invalid = []
    for raw in raw_fields:
        cleaned, valid = check_field(raw)
        lines.append(format_row(raw, cleaned, valid))
        if not valid:
            invalid.append(cleaned or "<empty>")
    total = len(raw_fields)
    lines.append("%d of %d fields valid" % (total - len(invalid), total))
    if invalid:
        lines.append("rejected: " + ', '.join(invalid))
    return '\n'.join(lines)


def main(argv):
    fields = argv[1:] or ['90210', '1234', ' 02134 ', '9021O', '00000', '123456']
    print(build_report(fields))
    return 0 if all(is_valid_us_zip_code(normalize(f)) for f in fields) else 1


if __name__ == "__main__":
    sys.exit(main(sys.argv))

