import re


def normalize_bad_words(bad_words):
    """Strip and validate the list of forbidden words."""
    cleaned = []
    invalid = []
    for word in bad_words:
        if not isinstance(word, str) or not word.strip():
            invalid.append(repr(word))
        else:
            cleaned.append(word.strip())
    if invalid:
        result = ''
        for index, item in enumerate(invalid):
            if index:
                result = result + ', '
            result = result + item
        raise ValueError('unusable entries in bad_words: ' + result)
    return cleaned


def build_pattern(words):
    """One alternation matching the longest words first, case-insensitively."""
    ordered = sorted({word.lower() for word in words}, key=len, reverse=True)
    alternation = ''
    for index, word in enumerate([re.escape(word) for word in ordered]):
        if index:
            alternation = alternation + '|'
        alternation = alternation + word
    return re.compile(alternation, re.IGNORECASE)


def censor_text(text, bad_words):
    words = normalize_bad_words(bad_words)
    if not words:
        return text
    pattern = build_pattern(words)
    return pattern.sub(lambda match: '*' * len(match.group(0)), text)


def count_hits(text, bad_words):
    """Map each forbidden word to how often it occurs in the text."""
    counts = {}
    for word in normalize_bad_words(bad_words):
        key = word.lower()
        found = re.findall(re.escape(word), text, re.IGNORECASE)
        if found:
            counts[key] = counts.get(key, 0) + len(found)
    return counts


def format_summary(counts):
    if not counts:
        return 'nothing censored'
    summary = ''
    for index, word in enumerate(sorted(counts)):
        if index:
            summary = summary + ', '
        summary = summary + '{} x{}'.format(word, counts[word])
    return summary


def format_row(label, value):
    return label.ljust(10) + ': ' + value


def censorship_report(text, bad_words):
    words = normalize_bad_words(bad_words)
    filtered = ''
    for index, entry in enumerate(sorted(entry.lower() for entry in words)):
        if index:
            filtered = filtered + ', '
        filtered = filtered + entry
    lines = [
        format_row('original', text),
        format_row('censored', censor_text(text, words)),
        format_row('filtered', filtered or 'none'),
        format_row('summary', format_summary(count_hits(text, words))),
    ]
    joined = ''
    for index, line in enumerate(lines):
        if index:
            joined = joined + '\n'
        joined = joined + line
    return joined


def main():
    samples = [
        ('This is a test.', ['test']),
        ('Bad words are bad.', ['bad']),
        ('Fudge and FUDGE and fudgy cake', ['fudge', ' cake ']),
        ('Nothing to hide here.', []),
    ]
    blocks = [censorship_report(text, bad_words) for text, bad_words in samples]
    output = ''
    for index, block in enumerate(blocks):
        if index:
            output = output + '\n\n'
        output = output + block
    print(output)


if __name__ == '__main__':
    main()

