def _validate(px, py, cx, cy, radius):
    """Reject non-numeric coordinates and negative radii before any math."""
    for name, value in (('px', px), ('py', py), ('cx', cx), ('cy', cy), ('radius', radius)):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(''.join([name, '=', repr(value), ' is not a real number']))
    if radius < 0:
        raise ValueError(''.join(['radius must be non-negative, got ', repr(radius)]))


def format_point(x, y):
    """Render a point as '(x, y)' with compact numbers."""
    return ''.join(['(', format(x, 'g'), ', ', format(y, 'g'), ')'])


def format_circle(cx, cy, radius):
    """Describe a circle by its centre and radius."""
    return ''.join(['circle centered at ', format_point(cx, cy), ' with radius ', format(radius, 'g')])


def is_point_in_circle(px, py, cx, cy, radius):
    """True if (px, py) lies inside or exactly on the given circle."""
    _validate(px, py, cx, cy, radius)
    dx = px - cx
    dy = py - cy
    return dx * dx + dy * dy <= radius * radius


def classify(px, py, cx, cy, radius):
    """Return 'inside', 'on boundary' or 'outside' for the point."""
    _validate(px, py, cx, cy, radius)
    dx = px - cx
    dy = py - cy
    squared = dx * dx + dy * dy
    limit = radius * radius
    if squared == limit:
        return 'on boundary'
    return 'inside' if squared < limit else 'outside'


def describe(px, py, cx, cy, radius):
    """Human readable sentence about the point's position."""
    where = classify(px, py, cx, cy, radius)
    return ''.join([format_point(px, py), ' lies ', where, ' of the ', format_circle(cx, cy, radius)])


def _row(point, circle, position, verdict):
    """Pad the four table cells into a single fixed-width line."""
    return ''.join([point.ljust(14), circle.ljust(22), position.ljust(12), verdict.ljust(8)])


def report(cases):
    """Build a fixed-width table for a sequence of (px, py, cx, cy, radius) tuples."""
    lines = [_row('point', 'circle', 'position', 'in?'), '-' * 56]
    for px, py, cx, cy, radius in cases:
        circle = format_circle(cx, cy, radius).replace('circle centered at ', '')
        verdict = str(is_point_in_circle(px, py, cx, cy, radius))
        lines.append(_row(format_point(px, py), circle, classify(px, py, cx, cy, radius), verdict))
    return lines


def main():
    cases = [
        (1, 1, 0, 0, 2),
        (3, 3, 0, 0, 2),
        (2, 0, 0, 0, 2),
        (-1.5, 0.5, -1, 1, 1.25),
        (5, 5, 5, 5, 0),
    ]
    for line in report(cases):
        print(line)
    print()
    print(describe(*cases[0]))
    print(describe(*cases[1]))
    contained = sum(1 for case in cases if is_point_in_circle(*case))
    print(''.join(['contained points: ', str(contained), ' of ', str(len(cases))]))


if __name__ == '__main__':
    main()

