def calculate_triangle_perimeter(side1, side2, side3):
    """Return the perimeter of a triangle with the given side lengths."""
    validate_sides(side1, side2, side3)
    return side1 + side2 + side3


def validate_sides(side1, side2, side3):
    """Raise ValueError if the three lengths cannot form a triangle."""
    for name, value in (('side1', side1), ('side2', side2), ('side3', side3)):
        if value <= 0:
            raise ValueError(''.join([name, ' must be positive, got ', format_length(value)]))
    a, b, c = sorted((side1, side2, side3))
    if a + b <= c:
        raise ValueError(''.join([
            'sides ', format_length(a), ' + ', format_length(b),
            ' <= ', format_length(c),
        ]))


def format_length(value):
    """Render a length without a trailing '.0' for whole numbers."""
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def classify(side1, side2, side3):
    """Name the triangle according to how many sides are equal."""
    a, b, c = sorted((side1, side2, side3))
    if a == c:
        return 'equilateral'
    if a == b or b == c:
        return 'isosceles'
    return 'scalene'


def describe(side1, side2, side3):
    """Build a one-line description of the triangle and its perimeter."""
    lengths = ' x '.join([format_length(side1), format_length(side2), format_length(side3)])
    perimeter = calculate_triangle_perimeter(side1, side2, side3)
    return ''.join([
        classify(side1, side2, side3).capitalize(),
        ' triangle ',
        lengths,
        ' -> perimeter ',
        format_length(perimeter),
    ])


def report(triangles):
    """Describe every triangle, reporting rejected ones inline."""
    lines = []
    for side1, side2, side3 in triangles:
        try:
            lines.append(describe(side1, side2, side3))
        except ValueError as error:
            rendered = ', '.join([format_length(side1), format_length(side2), format_length(side3)])
            lines.append(''.join(['Rejected (', rendered, '): ', str(error)]))
    return lines


def main():
    samples = [
        (3, 4, 5),
        (7.5, 6, 8.5),
        (2, 2, 2),
        (5, 5, 8),
        (1, 2, 10),
        (0, 4, 4),
    ]
    for line in report(samples):
        print(line)
    valid = samples[:4]
    total = sum(calculate_triangle_perimeter(*sides) for sides in valid)
    print(''.join([
        'Total perimeter of the ',
        str(len(valid)),
        ' valid samples: ',
        format_length(total),
    ]))


if __name__ == '__main__':
    main()

