import random


def validate_flips(flips):
    """Return the flip string upper-cased, rejecting any unknown symbols."""
    if not isinstance(flips, str):
        raise TypeError('flips must be a string')
    cleaned = ''.join([c.upper() for c in flips if not c.isspace()])
    bad = sorted({c for c in cleaned if c not in 'HT'})
    if bad:
        raise ValueError('invalid flip symbols: ' + ', '.join(bad))
    return cleaned


def split_runs(flips):
    """Break a flip string into consecutive runs of the same face."""
    runs = []
    for face in flips:
        if runs and runs[-1][0] == face:
            runs[-1][1] += 1
        else:
            runs.append([face, 1])
    return [(face, count) for face, count in runs]


def longest_coin_flip_streak(flips):
    """Length of the longest run of consecutive identical flips."""
    runs = split_runs(validate_flips(flips))
    if not runs:
        return 0
    return max(count for _, count in runs)


def simulate_flips(count, seed=None):
    """Build a random flip string of the requested length."""
    if count < 0:
        raise ValueError('count must be non-negative')
    rng = random.Random(seed)
    return ''.join([rng.choice('HT') for _ in range(count)])


def render_runs(runs):
    """Show the runs as blocks separated by pipes, e.g. 'HHH|TTT'."""
    return '|'.join([face * count for face, count in runs])


def summarise_counts(runs):
    """Describe how many runs of each face were seen."""
    tally = {}
    for face, _ in runs:
        tally[face] = tally.get(face, 0) + 1
    names = {'H': 'heads', 'T': 'tails'}
    return ', '.join('{} run(s) of {}'.format(tally[face], names[face])
                     for face in sorted(tally))


def report(flips):
    """Produce a multi-line human-readable report for one flip sequence."""
    cleaned = validate_flips(flips)
    runs = split_runs(cleaned)
    lines = ['sequence: ' + (cleaned or '(empty)')]
    if runs:
        lines.append('runs:     ' + render_runs(runs))
        lines.append('summary:  ' + summarise_counts(runs))
    lines.append('longest streak: {}'.format(longest_coin_flip_streak(cleaned)))
    return '\n'.join(lines)


def main():
    samples = ['HHHTTTHHHH', 'HTHTHT', '', 'h t t h h h h t t', simulate_flips(24, seed=7)]
    for sample in samples:
        print(report(sample))
        print('-' * 40)
    streaks = [longest_coin_flip_streak(s) for s in samples]
    print('all streaks: ' + ', '.join(str(n) for n in streaks))


if __name__ == '__main__':
    main()

