import re
from collections import Counter

HASHTAG_PATTERN = re.compile(r'#([A-Za-z0-9]+)')


def extract_hashtags(text):
    """Return every hashtag in text, without the '#', in original casing."""
    if not isinstance(text, str):
        raise TypeError(''.join([
            'extract_hashtags() expects a string, got ',
            type(text).__name__,
        ]))
    return HASHTAG_PATTERN.findall(text)


def unique_hashtags(text):
    """Hashtags in order of first appearance, compared case-insensitively."""
    seen = set()
    result = []
    for tag in extract_hashtags(text):
        key = tag.lower()
        if key not in seen:
            seen.add(key)
            result.append(tag)
    return result


def count_hashtags(text):
    """Map lowercase hashtag -> number of occurrences."""
    return Counter(tag.lower() for tag in extract_hashtags(text))


def strip_hashtags(text):
    """Remove the hashtags from text, leaving the surrounding words tidy."""
    pieces = HASHTAG_PATTERN.split(text)[::2]
    without_tags = ''.join(pieces)
    return ' '.join(without_tags.split())


def format_line(text):
    """One-line summary: the plain text followed by its tags."""
    tags = unique_hashtags(text)
    tag_part = ', '.join(tags) or '(no hashtags)'
    return ''.join([strip_hashtags(text), ' -- ', tag_part])


def build_report(messages):
    """Per-message summaries plus a totals section for a batch of messages."""
    lines = [format_line(message) for message in messages]
    totals = Counter()
    for message in messages:
        totals.update(count_hashtags(message))
    ranked = sorted(totals.items(), key=lambda item: (-item[1], item[0]))
    tally = ', '.join('#{0} x{1}'.format(tag, n) for tag, n in ranked)
    lines.append('-' * 40)
    lines.append(''.join(['totals: ', tally or 'none']))
    return '\n'.join(lines)


def main():
