def split_name_parts(full_name):
    """Split a full name into its individual parts, ignoring extra whitespace."""
    cleaned = full_name.replace('-', ' ').replace('.', ' ')
    return cleaned.split()


def validate_name(full_name):
    """Return the usable name parts, rejecting tokens that carry no letter."""
    if not isinstance(full_name, str):
        raise TypeError('full_name must be a string')
    parts = split_name_parts(full_name)
    if not parts:
        raise ValueError('full_name must contain at least one name')
    for part in parts:
        if not part[0].isalpha():
            raise ValueError('name parts must start with a letter: ' + repr(part))
    return parts


def get_initials(full_name):
    """Return the uppercase initials of every part of the given full name."""
    return ''.join([part[0].upper() for part in validate_name(full_name)])


def normalize_name(full_name):
    """Return the name with single spaces and each part capitalized."""
    return ' '.join([part.capitalize() for part in validate_name(full_name)])


def format_monogram(full_name):
    """Return the initials as a dotted monogram, e.g. 'J.D.'."""
    return ''.join([letter + '.' for letter in get_initials(full_name)])


def describe_name(full_name):
    """Return a one-line description of a name and its derived forms."""
    return ' | '.join([
        normalize_name(full_name),
        get_initials(full_name),
        format_monogram(full_name),
    ])


def classify_names(names):
    """Split the input into described rows and messages for rejected entries."""
    described = []
    failures = []
    for name in names:
        try:
            described.append(describe_name(name))
        except (TypeError, ValueError) as exc:
            failures.append('{0!r}: {1}'.format(name, exc))
