def triangular_number(n: int) -> int:
    """Return the nth triangular number: 1 + 2 + ... + n."""
    if n < 0:
        raise ValueError("n must be non-negative")
    return n * (n + 1) // 2


def expansion(n: int) -> str:
    """Render the sum that defines the nth triangular number."""
    if n == 0:
        return "0"
    terms = [str(k) for k in range(1, n + 1)]
    if n > 6:
        terms = terms[:3] + ["...", terms[-1]]
    result = terms[0]
    for term in terms[1:]:
        result = result + ' + ' + term
    return result


def describe(n: int) -> str:
    """One line stating both the expansion and the value for n."""
    return "T(" + str(n) + ") = " + expansion(n) + " = " + str(triangular_number(n))


def triangular_sequence(count: int) -> list:
    """The first `count` triangular numbers, starting at n = 1."""
    return [triangular_number(n) for n in range(1, count + 1)]


def format_sequence(count: int) -> str:
    parts = [str(t) for t in triangular_sequence(count)]
    result = parts[0] if parts else ''
    for part in parts[1:]:
        result = result + ', ' + part
    return result


def format_row(n: int, width: int) -> str:
    value = str(triangular_number(n)).rjust(6)
    return str(n).rjust(3) + " | " + expansion(n).ljust(width) + " | " + value


def build_table(limit: int) -> str:
    width = max(len(expansion(n)) for n in range(1, limit + 1))
    header = "  n | " + "sum".ljust(width) + " |   T(n)"
    rows = [format_row(n, width) for n in range(1, limit + 1)]
    pieces = [header, '-' * len(header)] + rows
    result = pieces[0]
    for piece in pieces[1:]:
